tokio::task_local! {
    static SLOT_CONTINUATION_OWNER: ParkedHoleAbortRegistration;
    static INVOCATION_CANCEL: Arc<std::sync::atomic::AtomicBool>;
    static COMPILER_CLOSE_OWNER: CompilerCloseOwner;
    static EXECUTION_CONTROL: Arc<crate::WorkbenchExecutionControl>;
}

#[derive(Clone)]
pub(crate) enum CompilerCloseOwner {
    ActorLifecycle(crate::RetainedActorExit),
    ActorFinalization(crate::RetainedActorExit),
    SharedPreparation {
        producer: crate::RetainedActorExit,
        observer: Box<CompilerCloseOwner>,
    },
    Hosted(Arc<crate::WorkbenchExecutionControl>),
    Invocation {
        work: Arc<crate::resident_actor::invocation_work::InvocationWork>,
        control: Option<Arc<crate::WorkbenchExecutionControl>>,
    },
}

impl CompilerCloseOwner {
    pub(crate) fn close_settled(&self) {
        match self {
            Self::ActorLifecycle(owner) | Self::ActorFinalization(owner) => {
                owner.notify_compiler_close()
            }
            Self::SharedPreparation { producer, observer } => {
                producer.notify_compiler_close();
                observer.close_settled();
            }
            Self::Hosted(control) => control.notify_compiler_close(),
            Self::Invocation { control, .. } => {
                if let Some(control) = control {
                    control.notify_compiler_close();
                }
            }
        }
    }

    pub(crate) fn scope<T>(
        &self,
        operation: impl std::future::Future<Output = T>,
    ) -> impl std::future::Future<Output = T> {
        COMPILER_CLOSE_OWNER.scope(self.clone(), operation)
    }
}

fn register_compiler_work(
) -> Result<crate::termination::CompilerWorkTicket, ResidentActorWorkbenchError> {
    CompilerCloseOwner::current()?.register_work()
}

#[derive(Clone, Copy)]
enum CompilerWorkAdmission {
    Active,
    Publication,
}

impl CompilerCloseOwner {
    /// Capture before spawning a task; Tokio task-local owners are not inherited.
    pub(crate) fn current() -> Result<Self, ResidentActorWorkbenchError> {
        COMPILER_CLOSE_OWNER
            .try_with(Clone::clone)
            .ok()
            .or_else(|| execution_control().map(Self::Hosted))
            .ok_or(ResidentActorWorkbenchError::CompilerCleanupOwnerUnavailable)
    }

    /// Admit before spawning native work. The affine ticket retains this exact
    /// lifetime and settles it even if every async waiter disappears.
    pub(crate) fn register_work(
        &self,
    ) -> Result<crate::termination::CompilerWorkTicket, ResidentActorWorkbenchError> {
        self.register_work_in(CompilerWorkAdmission::Active)
    }

    /// Only the publication entrypoint admits finalizer work after user effects stop.
    pub(crate) fn register_publication_work(
        &self,
    ) -> Result<crate::termination::CompilerWorkTicket, ResidentActorWorkbenchError> {
        self.register_work_in(CompilerWorkAdmission::Publication)
    }

    pub(crate) fn shared_preparation(&self, producer: crate::RetainedActorExit) -> Self {
        Self::SharedPreparation {
            producer,
            observer: Box::new(self.clone()),
        }
    }

    fn register_receipt(
        &self,
        receipt: crate::termination::CompilerWorkReceipt,
        admission: CompilerWorkAdmission,
    ) -> bool {
        match self {
            Self::ActorLifecycle(owner) => owner.register_compiler_work(receipt),
            Self::ActorFinalization(owner) => owner.register_compiler_finalization_work(receipt),
            Self::SharedPreparation { producer, observer } => {
                producer.register_compiler_work(receipt.clone())
                    && observer.register_receipt(receipt.observation_only(), admission)
            }
            Self::Hosted(owner) => owner.register_compiler_work(receipt),
            Self::Invocation { work, control } => {
                let admitted = match admission {
                    CompilerWorkAdmission::Active => work.register_compiler_work(receipt.clone()),
                    CompilerWorkAdmission::Publication => {
                        work.register_publication_compiler_work(receipt.clone())
                    }
                };
                admitted
                    && control
                        .as_ref()
                        .is_none_or(|owner| owner.register_compiler_work(receipt))
            }
        }
    }

    fn register_work_in(
        &self,
        admission: CompilerWorkAdmission,
    ) -> Result<crate::termination::CompilerWorkTicket, ResidentActorWorkbenchError> {
        let receipt = crate::termination::CompilerWorkReceipt::pending();
        let ticket = crate::termination::CompilerWorkTicket::new(receipt.clone(), self.clone());
        let admitted = self.register_receipt(receipt, admission);
        if admitted {
            return Ok(ticket);
        }
        // No native work has started. Revoke any partial metadata admission cleanly.
        ticket.consume(tidepool_runtime::CompilerTransactionOutcome {
            action: (),
            close: tidepool_runtime::CompilerTransactionClose::NotStarted,
        });
        Err(ResidentActorWorkbenchError::CompilerCleanupAdmissionClosed)
    }
}

/// Direct fixtures supply the existing lifecycle owner explicitly.
#[cfg(test)]
async fn with_test_compiler_owner<T>(operation: impl std::future::Future<Output = T>) -> T {
    let mut owner = crate::CompilerPreparationOwner::new();
    let cleanup = owner.cleanup();
    let result =
        futures_util::FutureExt::catch_unwind(std::panic::AssertUnwindSafe(owner.scope(operation)))
            .await;
    let observation = cleanup
        .wait_for_settlement(std::time::Duration::from_secs(5))
        .await;
    assert!(
        observation.is_confirmed(),
        "compiler cleanup: {observation:?}"
    );
    match result {
        Ok(outcome) => outcome.action,
        Err(panic) => std::panic::resume_unwind(panic),
    }
}

pub(crate) fn with_invocation_cancellation<T>(
    cancel: Arc<std::sync::atomic::AtomicBool>,
    operation: impl std::future::Future<Output = T>,
) -> impl std::future::Future<Output = T> {
    INVOCATION_CANCEL.scope(cancel, operation)
}

pub(crate) fn with_execution_control<T>(
    control: Arc<crate::WorkbenchExecutionControl>,
    operation: impl std::future::Future<Output = T>,
) -> impl std::future::Future<Output = T> {
    let cancel = control.native_cancel();
    EXECUTION_CONTROL.scope(control, with_invocation_cancellation(cancel, operation))
}

pub(crate) fn execution_control() -> Option<Arc<crate::WorkbenchExecutionControl>> {
    EXECUTION_CONTROL.try_with(Arc::clone).ok()
}

impl ActorWorkbenchSource {
    fn compile_inputs(
        &self,
        context: &crate::ActorSessionContext,
    ) -> Result<tidepool_runtime::session::RuntimeCompileInputs, ResidentActorWorkbenchError> {
        tidepool_runtime::session::RuntimeCompileInputs::new(
            self.request_annotations()
                .map_err(ResidentActorWorkbenchError::Compile)?,
            context.source_imports.declaration_projections()?,
        )
        .map_err(ResidentActorWorkbenchError::Compile)
    }

    fn request_annotations(
        &self,
    ) -> Result<Option<tidepool_runtime::session::RequestCompileAnnotations>, CompileError> {
        match &self.request_evidence {
            Some(evidence) => tidepool_runtime::session::RequestCompileAnnotations::new(
                evidence.clone(),
                self.request_helper_recipe,
            )
            .map(Some),
            None if self.request_helper_recipe
                == tidepool_toolchain::declaration_join::RequestHelperRecipe::None =>
            {
                Ok(None)
            }
            None => Err(CompileError::ExtractFailed(
                "actor reply helpers require authenticated request evidence".into(),
            )),
        }
    }

    fn request_preamble(&self, request: crate::RequestId, effects_alias: &str) -> String {
        let preamble = &self.preamble;
        let signatures = self
            .request_evidence
            .as_ref()
            .and_then(|evidence| evidence.request_type_signatures());
        let mut preamble = insert_preamble_imports(
            preamble,
            "qualified Tidepool.Agent.Reply.Internal as TidepoolReplies",
        );
        preamble = insert_preamble_imports(&preamble, "qualified Data.Void as TidepoolVoid");
        preamble = insert_preamble_imports(&preamble, "qualified Prelude as TidepoolPrelude");
        preamble.push_str(&format!(
            "\nsessionReply :: TidepoolReplies.Reply TidepoolRequestReply\nsessionReply = TidepoolReplies.Reply (TidepoolReplies.RequestId {})\nrespond :: TidepoolRequestReply -> Eff {effects_alias} TidepoolVoid.Void\nrespond = TidepoolReplies.reply sessionReply\n",
            request.0,
        ));
        if signatures
            .and_then(|signatures| signatures.progress())
            .is_some()
        {
            let progress_type = "TidepoolRequestProgress";
            preamble.push_str(&format!(
                "\nreportProgress :: ({progress_type}) -> Eff {effects_alias} ()\nreportProgress value = do\n  outcome <- TidepoolReplies.reportRequestProgress (TidepoolReplies.ProgressSink (TidepoolReplies.RequestId {})) value\n  case outcome of\n    Left failure -> TidepoolPrelude.error (TidepoolPrelude.show failure)\n    Right () -> pure ()\n", request.0,
            ));
        }
        preamble
    }
}

fn actor_preamble(preamble: &str, context: &crate::ActorSessionContext) -> String {
    let preamble = insert_preamble_imports(
        preamble,
        "qualified Tidepool.Agent.Ref.Internal as TidepoolAgentRef",
    );
    format!(
        "{preamble}\nme :: TidepoolAgentRef.AgentRef\nme = TidepoolAgentRef.internalAgentRef {} {}\n",
        context.actor.id.0, context.actor.incarnation.0
    )
}

// This header belongs to the trusted generated template, never authored cell text.
fn cell_module_preamble(
    preamble: &str,
    module: &str,
) -> Result<String, ResidentActorWorkbenchError> {
    let mut replaced = false;
    let rendered = preamble
        .split_inclusive('\n')
        .map(|line| {
            if !replaced
                && line.trim_start().starts_with("module ")
                && line.trim_end().ends_with(" where")
            {
                replaced = true;
                let newline = if line.ends_with('\n') { "\n" } else { "" };
                format!("module {module} where{newline}")
            } else {
                line.to_owned()
            }
        })
        .collect::<String>();
    if replaced {
        Ok(rendered)
    } else {
        Err(ResidentActorWorkbenchError::CompileInfrastructure(
            "resident cell preamble has no module declaration".into(),
        ))
    }
}

/// The same cell-check failure mapping every `prepare_cell` exit uses:
/// a genuine Haskell error becomes a rejectable [`CellCheck`] failure the
/// caller can present, anything else is infrastructure trouble.
/// When a cell GHC has already rejected has a declaration reaching for a name
/// an earlier statement binds, say so beside GHC's own diagnostics.
///
/// The scan that finds this shape is lexical and cannot see every way Haskell
/// binds a name (a case alternative, a record field, an operator containing
/// `<-`), so it explains a failure and never causes one: a cell GHC accepts is
/// never refused on its word. It speaks only when GHC's diagnostics name the
/// same binder, which keeps it quiet on failures it has nothing to do with.
fn explain_source_order(
    failure: &mut tidepool_runtime::session::CellCheckFailure,
    cell_source: &str,
) {
    let CompileError::Diagnostics(diagnostics) = &mut failure.error else {
        return;
    };
    let Some(collision) =
        tidepool_runtime::session::detect_hoisted_declaration_collision(cell_source)
    else {
        return;
    };
    if !diagnostics
        .iter()
        .any(|diagnostic| diagnostic.message.contains(&collision.binder_name))
    {
        return;
    }
    let line = u32::try_from(collision.declaration_line).unwrap_or(u32::MAX);
    diagnostics.push(tidepool_toolchain::diag::ExtractDiag {
        span: Some(tidepool_toolchain::diag::DiagSpan {
            file: "<cell>".to_string(),
            start_line: line,
            start_col: 1,
            end_line: line,
            end_col: 1,
        }),
        severity: tidepool_toolchain::diag::DiagnosticSeverity::Warning,
        message: collision.message(),
    });
}

fn cell_check_error(
    failure: tidepool_runtime::session::CellCheckFailure,
    cell_source: &str,
) -> ResidentActorWorkbenchError {
    if classify_compile(&failure.error).class == FailureClass::UserHaskell {
        let mut failure = failure;
        explain_source_order(&mut failure, cell_source);
        ResidentActorWorkbenchError::CellCheck(failure)
    } else {
        let mut diagnostic = classify_compile(&failure.error);
        diagnostic.message =
            tidepool_runtime::session::render_cell_compile_error(&failure.error, cell_source);
        ResidentActorWorkbenchError::CompileInfrastructure(diagnostic)
    }
}

#[cfg(test)]
mod failure_diagnostic_tests {
    use super::*;

    #[test]
    fn kernel_failure_roundtrip_keeps_compiler_diagnostic_and_plain_failure() {
        let compiler = ResidentActorWorkbenchError::Compile(CompileError::MissingOutput(
            PathBuf::from("captured-release.cbor"),
        ))
        .into_kernel_behavior_error();
        for original in [compiler, crate::KernelBehaviorError::new("scope released")] {
            let expected = original.clone();
            let retained = ResidentActorWorkbenchError::from(original);
            assert_eq!(retained.failure_diagnostic(), expected.diagnostic);
            assert_eq!(retained.into_kernel_behavior_error(), expected);
        }
    }

    #[test]
    fn activation_committed_failure_preserves_compiler_infrastructure_diagnostic() {
        let binding = tidepool_repr::SessionVarId::from_extract(41);
        let error = ResidentActorWorkbenchError::ActivationBindingCommitted {
            binding,
            source: Box::new(ResidentActorWorkbenchError::InputCompilation {
                stage: ActivationCompileStage::Preview,
                error: CompileError::MissingOutput(PathBuf::from("preview-receipt.cbor")),
            }),
        };
        let diagnostic = error
            .failure_diagnostic()
            .expect("committed diagnostic retained");
        assert_eq!(diagnostic.class, FailureClass::Infra);
        assert_eq!(
            diagnostic.cause,
            Some(tidepool_toolchain::failclass::CompileFailureCause::MissingOutput),
        );
        let ResidentActorWorkbenchError::ActivationBindingCommitted {
            binding: retained,
            source,
        } = error
        else {
            panic!("committed preview failure lost its disposition")
        };
        assert_eq!(retained, binding);
        assert!(source.to_string().contains("preview-receipt.cbor"));
    }

    #[test]
    fn activation_suspension_keeps_primary_and_abort_failure() {
        let error = ResidentActorWorkbenchError::ActivationBindingCommitted {
            binding: tidepool_repr::SessionVarId::from_extract(42),
            source: Box::new(ResidentActorWorkbenchError::ActivationPreviewSuspended {
                cleanup: Some(ResidentError::InvalidActivationInput { site: 43 }),
            }),
        };
        let rendered = error.to_string();
        assert!(rendered.contains("pure activation preview suspended"));
        assert!(rendered.contains("InvalidActivationInput"));
        assert!(rendered.contains("43"));
    }

    #[test]
    fn activation_compile_failure_keeps_stage_typed_diagnostics_and_bounded_text() {
        use tidepool_toolchain::diag::{DiagSpan, DiagnosticSeverity, ExtractDiag};
        for stage in [
            ActivationCompileStage::Interface,
            ActivationCompileStage::Preview,
        ] {
            let message = format!(
                "original compiler detail\n{}\nlast compiler detail",
                "λ".repeat(8192)
            );
            let error = ResidentActorWorkbenchError::InputCompilation {
                stage,
                error: CompileError::Diagnostics(vec![ExtractDiag {
                    span: Some(DiagSpan {
                        file: "CellCheck.hs".into(),
                        start_line: 46,
                        start_col: 3,
                        end_line: 46,
                        end_col: 19,
                    }),
                    severity: DiagnosticSeverity::Error,
                    message: message.clone(),
                }]),
            };
            let diagnostic = error.failure_diagnostic().unwrap();
            assert_eq!(diagnostic.class, FailureClass::UserHaskell);
            assert_eq!(
                diagnostic.cause,
                Some(tidepool_toolchain::failclass::CompileFailureCause::SourceDiagnostics,)
            );
            assert!(diagnostic.message.len() <= ACTIVATION_COMPILE_DIAGNOSTIC_BYTES);
            assert!(diagnostic.message.contains("CellCheck.hs:46:3"));
            assert!(diagnostic.message.contains("original compiler detail"));
            assert!(diagnostic.message.contains("last compiler detail"));
            assert!(error.to_string().contains(&stage.to_string()));
            assert!(error.to_string().contains("original compiler detail"));
            let ResidentActorWorkbenchError::InputCompilation {
                stage: retained_stage,
                error: CompileError::Diagnostics(retained),
            } = error
            else {
                panic!("typed compiler failure lost")
            };
            assert_eq!(retained_stage, stage);
            assert_eq!(retained[0].message, message);
        }
    }

    #[test]
    fn parser_failure_routes_source_only_and_preserves_non_source_classes() {
        use tidepool_toolchain::diag::{DiagnosticSeverity, ExtractDiag};
        let diagnostic = ExtractDiag {
            span: None,
            severity: DiagnosticSeverity::Error,
            message: "parse error λ".into(),
        };
        let source = cell_check_error(
            CompileError::Diagnostics(vec![diagnostic.clone()]).into(),
            ":}",
        );
        let ResidentActorWorkbenchError::CellCheck(source) = source else {
            panic!("authored parse failure must use source-aware rejection")
        };
        assert!(
            source.items.is_none(),
            "a parser failure has no accepted source plan"
        );
        let CompileError::Diagnostics(retained) = source.error else {
            panic!("source diagnostic lost")
        };
        assert_eq!(retained[0].message, diagnostic.message);
        for error in [
            CompileError::MissingOutput(PathBuf::from("missing-output")),
            CompileError::Io(std::io::Error::other("controlled IO failure")),
            CompileError::WorkerFailure(vec![diagnostic.clone()]),
            CompileError::InputRejected(vec![diagnostic]),
            CompileError::ExtractFailed("controlled contract failure".into()),
            CompileError::MalformedDiagnostics("controlled wire failure".into()),
        ] {
            let expected = classify_compile(&error);
            let mapped = cell_check_error(error.into(), ":}");
            assert!(matches!(
                mapped,
                ResidentActorWorkbenchError::CompileInfrastructure(_)
            ));
            let actual = mapped.failure_diagnostic().expect("classified failure");
            assert_eq!(actual.class, expected.class);
            assert_eq!(actual.phase, expected.phase);
            assert_eq!(actual.cause, expected.cause);
        }
    }

    #[test]
    fn preflight_infrastructure_failure_keeps_compiler_class_and_cause() {
        let failure =
            CompileError::MissingOutput(std::path::PathBuf::from("missing-output")).into();
        let error = cell_check_error(failure, "authored cell");
        let diagnostic = error
            .failure_diagnostic()
            .expect("compile failure classified");
        assert_eq!(diagnostic.class, FailureClass::Infra);
        assert_eq!(
            diagnostic.phase,
            tidepool_toolchain::failclass::Phase::Compile
        );
        assert_eq!(
            diagnostic.cause,
            Some(tidepool_toolchain::failclass::CompileFailureCause::MissingOutput)
        );
        assert!(error.to_string().contains("missing-output"));
        assert!(error
            .to_string()
            .starts_with("resident workbench compiler infrastructure failed:"));
    }
}

/// Trusted source environment supplied by actor deployment. The canonical
/// `ActorEffects` alias itself lives in the imported Haskell facade; Rust does
/// not reflect or authorize its row entries.
#[derive(Clone)]
pub struct ActorWorkbenchSource {
    preamble: Arc<str>,
    base_include: Arc<[PathBuf]>,
    workbench_imports: SourceImports,
    /// The workspace's `[haskell] spec` key, when it names one. Rule two of
    /// spec discovery; rule one is `AgentSpec.hs` in the run graph.
    spec: Option<Arc<str>>,
    workspace_modules: Arc<[String]>,
    installed_effect_support: Arc<[exomonad_tool::ToolEffectKey]>,
    request_evidence: Option<Arc<tidepool_runtime::session::SiteTypeEvidence>>,
    request_helper_recipe: tidepool_toolchain::declaration_join::RequestHelperRecipe,
    toolset_support: Arc<[PathBuf]>,
    toolset_support_manifests:
        Arc<std::sync::OnceLock<Vec<tidepool_toolchain::cache::SourceRootManifest>>>,
    toolset_preparation: Arc<crate::agent_spec::preparation::ToolsetPreparation>,
    prepared_toolset: Option<PreparedSourceToolset>,
}

/// Immutable installer readiness. It owns source and native code, while each
/// actor still executes its own installation in a fresh lexical scope.
#[derive(Clone)]
pub struct PreparedSourceToolset {
    prepared: Arc<crate::agent_spec::preparation::PreparedToolset>,
    effects: Vec<crate::ActorEffectKey>,
}

/// Observations of the exact installer recipe built by the preparation owner.
/// These fields describe coverage; they do not issue compiler or source custody.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SourceToolsetRecipe {
    pub requested_effects: Vec<crate::ActorEffectKey>,
    pub effective_effects: Vec<crate::ActorEffectKey>,
    pub source_revision: String,
    pub program: crate::ToolsetProgramRecipe,
}

impl std::fmt::Debug for PreparedSourceToolset {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("PreparedSourceToolset")
            .field("acquisition", self.acquisition())
            .field("effects", &self.effects)
            .finish()
    }
}

fn installer_program_recipe(
    recipe: &crate::agent_spec::preparation::InstallerRecipe,
) -> Result<crate::ToolsetProgramRecipe, ResidentActorWorkbenchError> {
    match &recipe.builtin {
        Some(program) => Ok(crate::ToolsetProgramRecipe::BuiltinDeploymentProgram(
            program.clone(),
        )),
        None => crate::agent_spec::preparation::durable_recipe_key(recipe)
            .map(crate::ToolsetProgramRecipe::WorkspaceOriginal)
            .map_err(|error| ResidentActorWorkbenchError::ActorProtocol(format!("{error:?}"))),
    }
}

fn builtin_toolset_policy(
    rule: crate::agent_spec::SpecRule,
    effects: &[crate::ActorEffectKey],
    supported: &[exomonad_tool::ToolEffectKey],
) -> Option<crate::BuiltinToolsetPolicy> {
    if rule != crate::agent_spec::SpecRule::BuiltinDefault
        || effects != crate::ActorCapabilities::default().effect_keys()
    {
        return None;
    }
    Some(
        if supported.contains(&exomonad_tool::ToolEffectKey::ContextReadWrite) {
            crate::BuiltinToolsetPolicy::Workbench
        } else {
            crate::BuiltinToolsetPolicy::AsyncWorkbench
        },
    )
}

impl PreparedSourceToolset {
    #[must_use]
    pub fn selection(&self) -> Option<crate::ToolsetProgramSelection> {
        self.prepared.acquisition.selection()
    }

    #[must_use]
    pub fn image_registry(&self) -> Arc<tidepool_runtime::session::ImageRegistry> {
        Arc::clone(self.prepared.entry.image_registry())
    }
    #[must_use]
    pub fn source_revision(&self) -> &str {
        &self.prepared.source_revision
    }

    #[must_use]
    pub fn effects(&self) -> &[crate::ActorEffectKey] {
        &self.effects
    }

    /// Provenance issued by the original preparation, retained across cache hits.
    #[must_use]
    pub fn acquisition(&self) -> &crate::ToolsetAcquisition {
        &self.prepared.acquisition
    }

    /// Exact completed output selected after full native readiness. This is
    /// retained-source metadata; loading still validates original custody.
    #[must_use]
    pub fn completed_entry_selection(&self) -> Option<(&str, uuid::Uuid)> {
        self.prepared.acquisition.completed_entry_selection()
    }
}

/// One prepared import environment for evaluation and inspection. Name
/// resolution comes from the exact lexical view before either path builds
/// a compiler request.
struct WorkbenchCompilation {
    preamble: String,
    imports: String,
    include: Vec<PathBuf>,
    injected: Vec<String>,
}

impl ActorWorkbenchSource {
    /// Prepare one exact granted and supported row from an owned immutable run
    /// source graph. Preparation does not install tools or borrow actor heaps.
    /// The caller selects urgency; required startup is foreground and optional
    /// warming is preparation work.
    pub async fn prepare_source_toolset(
        &self,
        workload: tidepool_toolchain::artifacts::CompileWorkload,
        source: crate::CheckpointSourceLayer,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
        registry: Arc<tidepool_runtime::session::ImageRegistry>,
    ) -> Result<PreparedSourceToolset, ResidentActorWorkbenchError> {
        let (recipe, resolved) =
            self.installer_recipe(&source, granted_effects, supported_effects)?;
        let effects = recipe.effects.clone();
        if let Some(ready) = &self.prepared_toolset {
            let exact_selection = match ready.selection() {
                Some(crate::ToolsetProgramSelection::BuiltinDeploymentProgram { .. }) => true,
                Some(crate::ToolsetProgramSelection::WorkspaceOriginal { recipe, original }) => {
                    matches!(source.prepared_entries(), Some(crate::SourceEntryStorage::CompletedOriginal { selections, .. })
                        if selections.get(&recipe) == Some(&original))
                }
                None => false,
            };
            if ready.effects == effects
                && exact_selection
                && ready.selection().map(|selection| selection.recipe())
                    == Some(installer_program_recipe(&recipe)?)
            {
                return Ok(ready.clone());
            }
        }
        let prepared = self
            .toolset_preparation
            .prepare(workload, recipe, resolved, source, registry)
            .await
            .map_err(|failure| match failure {
                crate::agent_spec::preparation::PreparationFailure::AbsentSelection { recipe } => {
                    ResidentActorWorkbenchError::PreparedEntryAbsent { recipe }
                }
                crate::agent_spec::preparation::PreparationFailure::Admission(error) => {
                    ResidentActorWorkbenchError::PreparationAdmission(error)
                }
                crate::agent_spec::preparation::PreparationFailure::Compiler(diagnostic) => {
                    ResidentActorWorkbenchError::CompileInfrastructure(diagnostic)
                }
                crate::agent_spec::preparation::PreparationFailure::Source(detail)
                | crate::agent_spec::preparation::PreparationFailure::Native(detail) => {
                    ResidentActorWorkbenchError::ActorProtocol(detail)
                }
            })?;
        Ok(PreparedSourceToolset { prepared, effects })
    }

    /// Recompute deployment coverage against the same source, imports and
    /// actual interpreter support used by installer acquisition, without
    /// looking up readiness or admitting compiler work.
    pub fn source_toolset_recipe(
        &self,
        source: &crate::CheckpointSourceLayer,
        requested_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
    ) -> Result<SourceToolsetRecipe, ResidentActorWorkbenchError> {
        let (recipe, _) = self.installer_recipe(source, requested_effects, supported_effects)?;
        let program = installer_program_recipe(&recipe)?;
        Ok(SourceToolsetRecipe {
            requested_effects: requested_effects.to_vec(),
            effective_effects: recipe.effects,
            source_revision: recipe.source_revision,
            program,
        })
    }

    fn installer_recipe(
        &self,
        source: &crate::CheckpointSourceLayer,
        granted_effects: &[crate::ActorEffectKey],
        supported_effects: &[exomonad_tool::ToolEffectKey],
    ) -> Result<
        (
            crate::agent_spec::preparation::InstallerRecipe,
            crate::agent_spec::ResolvedSpec,
        ),
        ResidentActorWorkbenchError,
    > {
        let mut effects = Vec::new();
        for key in granted_effects {
            if supported_effects.contains(&exomonad_tool::ToolEffectKey::Actor(*key))
                && !effects.contains(key)
            {
                effects.push(*key);
            }
        }
        let mut roots = self.toolset_support.to_vec();
        roots.extend(source.include_paths().iter().cloned());
        let roots = roots
            .into_iter()
            .map(std::fs::canonicalize)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| ResidentActorWorkbenchError::ActorProtocol(error.to_string()))?;
        let resolved = crate::agent_spec::resolve(roots.clone(), self.spec.as_deref());
        let builtin = if let Some(policy) =
            builtin_toolset_policy(resolved.rule, &effects, supported_effects)
        {
            // Observe the current deployment selection before reusing issuer-owned
            // readiness. This reads metadata without decoding its native images.
            crate::agent_spec::preparation::builtin_program(policy)
                .map_err(|error| ResidentActorWorkbenchError::ActorProtocol(format!("{error:?}")))?
        } else {
            None
        };
        if let Some(program) = builtin {
            return Ok((
                crate::agent_spec::preparation::InstallerRecipe {
                    source_authority: None,
                    source_revision: program.manifest_blake3.clone(),
                    roots: Vec::new(),
                    preamble: String::new(),
                    imports: String::new(),
                    entry: match program.policy {
                        crate::BuiltinToolsetPolicy::Workbench => {
                            "Tidepool.Agent.Contract.installDefaultWorkbench"
                        }
                        crate::BuiltinToolsetPolicy::AsyncWorkbench => {
                            "Tidepool.Agent.Contract.installDefaultAsyncWorkbench"
                        }
                    }
                    .into(),
                    effects,
                    builtin: Some(program),
                },
                resolved,
            ));
        }
        let source_revision = if let Some(manifests) = source.source_manifests() {
            if manifests.len() != source.include_paths().len() {
                return Err(ResidentActorWorkbenchError::ActorProtocol(
                    "source owner's ordered manifest count differs from its roots".into(),
                ));
            }
            if self.toolset_support_manifests.get().is_none() {
                let captured = self
                    .toolset_support
                    .iter()
                    .map(|root| {
                        let files = tidepool_toolchain::cache::source_root_manifest(root)
                            .map_err(|error| error.to_string())?;
                        tidepool_toolchain::cache::SourceRootManifest::from_file_digests(files)
                            .map_err(|error| error.to_string())
                    })
                    .collect::<Result<Vec<_>, String>>()
                    .map_err(ResidentActorWorkbenchError::ActorProtocol)?;
                // A failed acquisition is retryable. Concurrent successful
                // acquisitions observe the same immutable deployment roots.
                let _ = self.toolset_support_manifests.set(captured);
            }
            let support = self
                .toolset_support_manifests
                .get()
                .expect("support acquired");
            let ordered = support.iter().chain(manifests).cloned().collect::<Vec<_>>();
            tidepool_toolchain::cache::source_manifests_identity(
                b"exomonad-agent-spec-ordered-source-closure-v1",
                &ordered,
            )
        } else {
            resolved
                .source_closure_revision()
                .map_err(ResidentActorWorkbenchError::ActorProtocol)?
        };
        let entry = resolved.entry.clone().unwrap_or_else(|| {
            if supported_effects.contains(&exomonad_tool::ToolEffectKey::ContextReadWrite) {
                "Tidepool.Agent.Contract.defaultWorkbenchSpec".into()
            } else {
                "Tidepool.Agent.Contract.defaultAsyncWorkbenchSpec".into()
            }
        });
        let mut imports = SourceImports::default();
        if let Some((module, _)) = entry.rsplit_once('.') {
            imports.extend_text(&format!("qualified {module}"));
        }
        imports.extend_text("qualified Tidepool.Agent.Contract");
        imports.extend_text("qualified Tidepool.Effects.Core");
        imports = crate::agent_spec::installation_expression(&entry, &effects)
            .effect_row
            .source_imports(&imports);
        Ok((
            crate::agent_spec::preparation::InstallerRecipe {
                builtin: None,
                source_authority: Some(source.semantic_digest()),
                source_revision,
                roots,
                preamble: format!(
                    "{}\nmodule Expr where\nimport Prelude\nimport Control.Monad.Freer (Eff)\nimport qualified Data.Text as T\n{}",
                    tidepool_runtime::session::EVAL_PRAGMAS,
                    tidepool_runtime::session::PREAMBLE_IMPORT_MARKER
                ),
                imports: imports.template_text(),
                entry,
                effects,
            },
            resolved,
        ))
    }

    fn prepare(&self, scope: &crate::ActorCompileView) -> WorkbenchCompilation {
        WorkbenchCompilation {
            preamble: scope.shadow_preamble(&hide_preamble_exports(
                &self.preamble,
                &["print"]
                    .map(|name| tidepool_runtime::session::ExportItem::Value { name: name.into() }),
            )),
            imports: scope.turn_imports(),
            include: scope.include_paths(&self.base_include),
            injected: scope.injected_module_names(),
        }
    }

    #[must_use]
    pub fn new(preamble: impl Into<Arc<str>>, base_include: Vec<PathBuf>) -> Self {
        Self {
            preamble: preamble.into(),
            toolset_support: base_include.clone().into(),
            toolset_support_manifests: Default::default(),
            base_include: base_include.into(),
            workbench_imports: SourceImports::from_specs([
                "qualified Data.Set as Set",
                "Tidepool.Inspection (display, expand, expansions)",
                "qualified Tidepool.Effects.Core",
                "qualified Tidepool.Lookup as LookupApi",
            ]),
            spec: None,
            workspace_modules: Arc::from([]),
            installed_effect_support: Arc::from([]),
            request_evidence: None,
            request_helper_recipe: Default::default(),
            toolset_preparation: Default::default(),
            prepared_toolset: None,
        }
    }

    /// Carry only immutable issuer-owned readiness into immediate launch.
    #[must_use]
    pub fn with_prepared_toolset(mut self, ready: Option<PreparedSourceToolset>) -> Self {
        self.prepared_toolset = ready;
        self
    }

    /// Deployment-owned support roots, ahead of the source owner's published
    /// toolset graph. Notebook/helper roots do not enter installer construction.
    #[must_use]
    pub fn with_toolset_support_roots(mut self, roots: Vec<PathBuf>) -> Self {
        self.toolset_support = roots.into();
        self.toolset_support_manifests = Default::default();
        self
    }

    /// Capture support from the actual assembled interpreter instances and
    /// installed host services, before admitting source-authored tools.
    #[must_use]
    pub fn with_installed_effect_support(
        mut self,
        keys: impl IntoIterator<Item = exomonad_tool::ToolEffectKey>,
    ) -> Self {
        let mut installed = Vec::new();
        for key in keys {
            if !installed.contains(&key) {
                installed.push(key);
            }
        }
        self.installed_effect_support = installed.into();
        self
    }

    pub(crate) fn installed_effect_support(&self) -> &[exomonad_tool::ToolEffectKey] {
        &self.installed_effect_support
    }

    /// Name the workspace-authored Haskell modules already compiled into
    /// every session and imported into every actor's preamble, so the doc
    /// catalog can list them beside the built-in topics. Absent for the
    /// operator workbench and tests, which have no `FrozenWorkspace`.
    #[must_use]
    pub fn with_workspace_modules(
        mut self,
        modules: impl IntoIterator<Item = impl Into<String>>,
    ) -> Self {
        self.workspace_modules = modules.into_iter().map(Into::into).collect();
        self
    }

    /// Preload the small quasiquoter vocabulary promised by a hosted
    /// workbench. Deployment selects this policy; the generic actor engine
    /// does not inspect input text or depend on an MCP-specific parser.
    #[must_use]
    pub fn with_default_quasiquoters(mut self) -> Self {
        self.workbench_imports
            .extend_text("Tidepool.QQ (fmt, j, patch, uri)");
        self
    }

    /// The import block every cell of this workbench compiles against, before
    /// a session view adds its own declaration and value modules. The compiler
    /// warm-up reads it so the graph it primes is the graph a cell reaches.
    #[must_use]
    pub fn workbench_import_text(&self) -> String {
        self.workbench_imports.template_text()
    }

    /// Additional shared imports must enter declaration compilation as well as
    /// expression templates, so bindings keep the same vocabulary after a fork.
    #[must_use]
    pub fn with_imports(mut self, imports: &str) -> Self {
        self.workbench_imports.extend_text(imports);
        self
    }

    /// Select the workspace's `[haskell] spec` value — rule two of spec
    /// discovery, for a workspace that wants a name other than
    /// `AgentSpec.agentSpec`. The installer owns its import; this selection
    /// does not expose the policy module to authored notebook cells.
    #[must_use]
    pub fn with_spec(mut self, entry: impl Into<Arc<str>>) -> Self {
        self.spec = Some(entry.into());
        self
    }

    /// [`Self::with_spec`] when the workspace named one, and nothing when it
    /// did not.
    #[must_use]
    pub fn with_spec_if(self, entry: Option<&str>) -> Self {
        match entry {
            Some(entry) => self.with_spec(entry),
            None => self,
        }
    }
}

/// One installed spec: the surface it declares, the retained value every call
/// and every slot is an application of, and the identity of this install.
pub(crate) struct ResidentWorkbenchTools {
    pub(crate) declarations: Vec<exomonad_tool::HostedTool>,
    pub(crate) dispatch: Arc<RootCustody>,
    /// Installer source roots belong to the installed implementation, not the
    /// actor's published declaration and value surface.
    _installation_scope: Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
    /// Exact source selection retained with a prepared candidate or installation.
    _source_original: Option<Arc<tidepool_toolchain::artifacts::PublishedSourceOriginalSelection>>,
    code: InstalledToolCode,
    /// Exact installer row retained with its rooted dispatcher.
    pub(crate) dispatcher_effects: tidepool_runtime::session::HaskellTypeSource,
    /// Which slots the installed record fills, by name, as the same compile
    /// declared them.
    pub(crate) slots: Vec<String>,
    /// How the spec was found, and where. Reported in status and in every
    /// reload receipt.
    pub(crate) origin: crate::agent_spec::SpecOrigin,
    /// Which install this record is, counting from one within this actor
    /// incarnation. A completed call names it, so a receipt says which record
    /// served the call and not merely which record is active now.
    pub(crate) install: u64,
    /// The source revision this record was built from, when the actor has a
    /// layer of its own to name one.
    ///
    /// This says which installed record served a call and what revision that
    /// record was compiled against. It does NOT say that every function
    /// reachable through the call belongs to one revision, which would be a
    /// different and possibly false claim.
    pub(crate) revision: Option<String>,
}

/// A public application's receiver retains its source domain independently of tool reloads.
pub(crate) struct PreparedRequestReceiver {
    pub(crate) entry: RootCustody,
    pub(crate) scope: Arc<tidepool_runtime::session::RuntimeLexicalScopeLease>,
}

#[derive(Clone, Copy)]
enum ToolInstallationPurpose {
    InitialTools,
    CandidateTools,
    SpawnApplication,
}

struct PreparedToolInstallation {
    tools: ResidentWorkbenchTools,
    receiver: Option<PreparedRequestReceiver>,
}

/// Code and values retained by the installation's real producer.
enum InstalledToolCode {
    SourcePrepared(Arc<crate::agent_spec::preparation::PreparedToolset>),
    ExplicitLive(Arc<RootCustody>),
}

impl InstalledToolCode {
    fn prepared(&self) -> Option<&Arc<crate::agent_spec::preparation::PreparedToolset>> {
        match self {
            Self::SourcePrepared(prepared) => Some(prepared),
            Self::ExplicitLive(_) => None,
        }
    }
}

/// Captured installer sent through the target actor's ordinary mailbox.
pub struct SpecReplacementDefinition {
    pub(crate) caller: crate::ActorRef,
    pub(crate) installer: RootCustody,
    pub(crate) session: tidepool_repr::SessionId,
    pub(crate) effects: Vec<crate::ActorEffectKey>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SpecReplacementError {
    Unavailable,
    Unauthorized,
    SurfaceChanged,
    Failed(String),
}

/// Authority over one actor's installed handler and immutable source revision.
/// The handler root remains live while an issued request retains this value.
#[derive(Clone)]
pub struct InstalledToolLease {
    actor: crate::ActorRef,
    source: crate::CheckpointSourceLayer,
    tools: Option<Arc<ResidentWorkbenchTools>>,
}

/// One original installed handler, retaining its actor and source authority.
pub(crate) struct InstalledToolHandler {
    actor: crate::ActorRef,
    _source: crate::CheckpointSourceLayer,
    tools: Arc<ResidentWorkbenchTools>,
}

impl InstalledToolHandler {
    pub(crate) fn actor(&self) -> crate::ActorRef {
        self.actor
    }

    pub(crate) fn tools(&self) -> &ResidentWorkbenchTools {
        &self.tools
    }
}

impl InstalledToolLease {
    pub(crate) fn new(
        actor: crate::ActorRef,
        source: crate::CheckpointSourceLayer,
        tools: Option<Arc<ResidentWorkbenchTools>>,
    ) -> Self {
        Self {
            actor,
            source,
            tools,
        }
    }

    pub(crate) fn actor(&self) -> crate::ActorRef {
        self.actor
    }

    pub(crate) fn source(&self) -> &crate::CheckpointSourceLayer {
        &self.source
    }

    pub(crate) fn tools(&self) -> Option<&ResidentWorkbenchTools> {
        self.tools.as_deref()
    }

    #[must_use]
    pub fn toolset_acquisition(&self) -> Option<&crate::ToolsetAcquisition> {
        self.tools
            .as_ref()
            .and_then(|tools| tools.code.prepared().map(|prepared| &prepared.acquisition))
    }

    pub(crate) fn tools_arc(&self) -> Option<Arc<ResidentWorkbenchTools>> {
        self.tools.clone()
    }

    pub(crate) fn handler(&self) -> Option<InstalledToolHandler> {
        Some(InstalledToolHandler {
            actor: self.actor,
            _source: self.source.clone(),
            tools: self.tools.clone()?,
        })
    }

    pub(crate) fn with_source(&self, source: crate::CheckpointSourceLayer) -> Self {
        Self {
            source,
            ..self.clone()
        }
    }
}

/// The actor's single current installation. Requests clone an immutable lease;
/// spec reload replaces the paired source and handlers at source visibility.
#[derive(Default)]
pub(crate) struct InstalledToolsState(Mutex<InstalledToolsAvailability>);

#[derive(Default)]
enum InstalledToolsAvailability {
    #[default]
    Empty,
    Available(InstalledToolLease),
    SourceUnavailable {
        actor: crate::ActorRef,
        tools: Option<Arc<ResidentWorkbenchTools>>,
    },
}

pub(crate) enum InstalledToolsObservation {
    Empty,
    Available(Option<Arc<ResidentWorkbenchTools>>),
    SourceUnavailable(Option<Arc<ResidentWorkbenchTools>>),
}

impl InstalledToolsAvailability {
    fn available(&self) -> Option<&InstalledToolLease> {
        match self {
            Self::Available(lease) => Some(lease),
            Self::Empty | Self::SourceUnavailable { .. } => None,
        }
    }
}

impl InstalledToolsState {
    pub(crate) fn observe(&self) -> InstalledToolsObservation {
        match &*self.0.lock() {
            InstalledToolsAvailability::Empty => InstalledToolsObservation::Empty,
            InstalledToolsAvailability::Available(lease) => {
                InstalledToolsObservation::Available(lease.tools_arc())
            }
            InstalledToolsAvailability::SourceUnavailable { tools, .. } => {
                InstalledToolsObservation::SourceUnavailable(tools.clone())
            }
        }
    }

    pub(crate) fn current(&self) -> Option<InstalledToolLease> {
        self.0.lock().available().cloned()
    }

    pub(crate) fn publish(&self, lease: InstalledToolLease) {
        *self.0.lock() = InstalledToolsAvailability::Available(lease);
    }

    pub(crate) fn current_tools(&self) -> Option<Arc<ResidentWorkbenchTools>> {
        self.current()?.tools_arc()
    }

    pub(crate) fn publish_source(
        &self,
        actor: crate::ActorRef,
        source: crate::CheckpointSourceLayer,
    ) {
        let mut current = self.0.lock();
        let previous = std::mem::take(&mut *current);
        *current = InstalledToolsAvailability::Available(match previous {
            InstalledToolsAvailability::Available(lease) => {
                assert_eq!(
                    lease.actor(),
                    actor,
                    "source publication belongs to the installed actor"
                );
                lease.with_source(source)
            }
            InstalledToolsAvailability::SourceUnavailable {
                actor: owner,
                tools,
            } => {
                assert_eq!(
                    owner, actor,
                    "source recovery belongs to the installed actor"
                );
                InstalledToolLease::new(actor, source, tools)
            }
            InstalledToolsAvailability::Empty => InstalledToolLease::new(actor, source, None),
        });
    }

    /// Fence the exact installation before entering the source owner's gate.
    /// Publication invokes the synchronous callback only after its visible rename.
    pub(crate) fn commit_spec_reload(
        &self,
        expected: &InstalledToolLease,
        tools: Arc<ResidentWorkbenchTools>,
        staged: Box<dyn crate::StagedActorSourceReload>,
        publication: &Arc<tidepool_runtime::session::PublicationDecision>,
    ) -> crate::SourceLayerReload {
        let replacement =
            InstalledToolLease::new(expected.actor(), staged.source().clone(), Some(tools));
        let mut current = self.0.lock();
        let matches = current.available().is_some_and(|current| {
            current.actor() == expected.actor()
                && current.source().semantic_digest() == expected.source().semantic_digest()
                && current
                    .tools()
                    .zip(expected.tools())
                    .is_some_and(|(current, expected)| {
                        Arc::ptr_eq(&current.dispatch, &expected.dispatch)
                    })
        });
        if !matches {
            return crate::SourceLayerReload::Unavailable(
                "the active source or installed handlers changed during preparation".into(),
            );
        }
        staged.commit(
            publication,
            Box::new(|| *current = InstalledToolsAvailability::Available(replacement)),
        )
    }

    /// Publish against the exact admitted implementation. Accepted calls retain
    /// their immutable lease, including when this actor replaces its own tools.
    pub(crate) fn replace_explicit(
        &self,
        expected: &InstalledToolLease,
        tools: Arc<ResidentWorkbenchTools>,
    ) -> Result<(), SpecReplacementError> {
        let mut current = self.0.lock();
        let active = current
            .available()
            .ok_or(SpecReplacementError::Unavailable)?;
        if active.actor() != expected.actor()
            || active.source().semantic_digest() != expected.source().semantic_digest()
            || !active
                .tools_arc()
                .zip(expected.tools_arc())
                .is_some_and(|(active, expected)| Arc::ptr_eq(&active, &expected))
        {
            return Err(SpecReplacementError::Unavailable);
        }
        let old = active.tools().ok_or(SpecReplacementError::Unavailable)?;
        if !exomonad_tool::surface::compare_surfaces(&old.declarations, &tools.declarations)
            .is_empty()
        {
            return Err(SpecReplacementError::SurfaceChanged);
        }
        *current = InstalledToolsAvailability::Available(InstalledToolLease::new(
            expected.actor(),
            expected.source().clone(),
            Some(tools),
        ));
        Ok(())
    }

    /// Refuse new source/tool snapshots while retaining the unchanged handlers
    /// for a later helper-source recovery. Retirement releases this custody.
    pub(crate) fn invalidate_source(&self) {
        let mut current = self.0.lock();
        *current = match std::mem::take(&mut *current) {
            InstalledToolsAvailability::Available(lease) => {
                InstalledToolsAvailability::SourceUnavailable {
                    actor: lease.actor(),
                    tools: lease.tools_arc(),
                }
            }
            unavailable => unavailable,
        };
    }

    pub(crate) fn clear(&self) {
        *self.0.lock() = InstalledToolsAvailability::Empty;
    }
}

pub(crate) use crate::tool_contract::{decode_installation, SpecInstallation};

impl ResidentWorkbenchTools {
    /// The provenance a completed call records: this record, and the revision
    /// it was built from.
    pub(crate) fn provenance(&self) -> String {
        format!(
            "install={} revision={} {}",
            self.install,
            self.revision.as_deref().unwrap_or("(run)"),
            self.origin.describe()
        )
    }
}

/// Shared-machine registry shape used by actors. String holes are only the
/// registry's checkout index; obligation-carrying `ResidentHole` values stay
/// inside each running segment.
pub type ActorMachineRegistry<H, O> = SessionRegistry<ResidentSession<H, O>, String>;

/// Read-only counters for matched resident performance measurements.
///
/// Every value comes from the session's existing codegen, heap, or residency
/// authority. `None` means the prepared machine has not bootstrapped yet;
/// callers must preserve that distinction instead of reporting zero.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
pub struct ResidentMachineMeasurement {
    pub native_functions: Option<u64>,
    pub native_code_bytes: Option<u64>,
    pub live_old_bytes: Option<usize>,
    pub major_collections: Option<u64>,
    pub programs: Option<usize>,
    pub block_words: Option<usize>,
    pub persistent_roots: Option<usize>,
    pub handles: Option<usize>,
    pub code_exports: Option<usize>,
    pub parked: Option<usize>,
    pub static_regions: Option<usize>,
    pub descriptor_rows: Option<usize>,
    pub callable_rows: Option<usize>,
    pub enter_rows: Option<usize>,
}

impl ResidentMachineMeasurement {
    fn of<H, O>(session: &ResidentSession<H, O>) -> Self
    where
        H: DispatchEffect<O> + Send,
        O: OutputSink + Sync,
    {
        let residency = session.residency();
        let codegen = session.codegen_totals();
        let heap = session.heap_stats();
        Self {
            native_functions: codegen.map(|(functions, _)| functions),
            native_code_bytes: codegen.map(|(_, bytes)| bytes),
            live_old_bytes: heap.map(|stats| stats.live_bytes),
            major_collections: heap.map(|stats| stats.gc_count),
            programs: residency.map(|counts| counts.programs),
            block_words: residency.map(|counts| counts.block_words),
            persistent_roots: residency.map(|counts| counts.persistent_roots),
            handles: residency.map(|counts| counts.handles),
            code_exports: residency.map(|counts| counts.code_exports),
            parked: residency.map(|counts| counts.parked),
            static_regions: residency.map(|counts| counts.static_regions),
            descriptor_rows: residency.map(|counts| counts.descriptor_rows),
            callable_rows: residency.map(|counts| counts.callable_rows),
            enter_rows: residency.map(|counts| counts.enter_rows),
        }
    }
}

/// The fixed nominal type and compiler recipe for an original host binding.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum HostCarrierKind {
    Job,
    Json,
    Text,
}

impl HostCarrierKind {
    fn host_binding_type(self) -> HostBindingType {
        match self {
            HostCarrierKind::Job => HostBindingType::COMMAND_JOB,
            HostCarrierKind::Json => HostBindingType::JSON_VALUE,
            HostCarrierKind::Text => HostBindingType::TEXT,
        }
    }

    fn type_name(self) -> &'static str {
        match self {
            HostCarrierKind::Job => COMMAND_JOB_TYPE_NAME,
            HostCarrierKind::Json => JSON_INPUT_TYPE_NAME,
            HostCarrierKind::Text => TEXT_BINDING_TYPE_NAME,
        }
    }

    fn anchor(self) -> &'static str {
        match self {
            HostCarrierKind::Job => COMMAND_JOB_ANCHOR,
            HostCarrierKind::Json => JSON_INPUT_ANCHOR,
            HostCarrierKind::Text => TEXT_BINDING_ANCHOR,
        }
    }

    fn imports(self) -> SourceImports {
        match self {
            HostCarrierKind::Job => command_job_carrier_imports(),
            HostCarrierKind::Json => json_input_carrier_imports(),
            HostCarrierKind::Text => text_binding_carrier_imports(),
        }
    }
}

/// Shared checkout boundary for every actor machine entry path. Fenced
/// fragments and installed actor programs differ above this layer, but use
/// exactly the same admission and settlement mechanism. Every checkout
/// installs the supplied actor context before invoking its operation, so a
/// child cannot leak its lexical scope, runtime resource scope, or principal into the
/// next parent or sibling entry.
///
/// An immutable observation of the actual handler instances in a checkout.
pub type HandlerEffectSupport<H> =
    Arc<dyn Fn(&H) -> Vec<exomonad_tool::ToolEffectKey> + Send + Sync + 'static>;

struct ResidentMachineAccess<H, O> {
    machines: Arc<ActorMachineRegistry<H, O>>,
    source: ActorWorkbenchSource,
    handler_effect_support: HandlerEffectSupport<H>,
    /// Builds a fresh, idle machine for a session id this host has decided
    /// deserves its own — installed once by the composition root; `None`
    /// keeps every launch on the shared session, unchanged, which is also
    /// today's behavior everywhere this hasn't been wired up yet. See
    /// [`crate::start::child_session_eligibility`] for the one caller that
    /// consults this.
    child_session_factory: Option<ChildSessionFactory<H, O>>,
    /// The compiled turn a fresh child session bootstraps with before
    /// anything imports into it — the SAME program the composition root
    /// itself bootstrapped with (`bridge/facade`'s `compile_root`), so a
    /// child's image matches the parent's for whatever a transferred entry's
    /// constituent objects need to resolve. Installed once by the
    /// composition root, alongside [`Self::child_session_factory`]; `None`
    /// makes [`ResidentActorRunner::provision_child_session`] refuse
    /// (there's a factory but nothing to bootstrap the machine it builds
    /// with — `ResidentSession::import_parcel` and `set_image_registry` both
    /// require an already-bootstrapped engine).
    child_bootstrap_program: Option<Arc<tidepool_runtime::session::CompiledTurn>>,
    /// This run's shared [`tidepool_runtime::session::ImageRegistry`], if
    /// the composition root installed one — `None` leaves every session
    /// compiling its own images, unchanged. Applied to a session's engine
    /// on every checkout ([`Self::with_host_machine`]): a no-op before that
    /// session's own first turn bootstraps its engine (there is nothing yet
    /// to share an image with — see
    /// [`tidepool_runtime::session::ResidentSession::set_image_registry`]),
    /// so a session's bootstrap install is never a hit, but every later
    /// install on that session, root or child alike, can be.
    image_registry: Option<Arc<tidepool_runtime::session::ImageRegistry>>,
    /// Sessions `provision_child_session` built — a launch's OWN
    /// dedicated machine, as opposed to the run's single shared session
    /// (never a member here, and never torn down). Membership is what makes
    /// a session id eligible for `ResidentActorRunner::retire_child_session`
    /// at all.
    child_sessions: Arc<std::sync::Mutex<std::collections::HashSet<tidepool_repr::SessionId>>>,
    /// Dedicated child sessions whose actor has retired but whose machine
    /// still held at least one live value handle. Each entry owns the one
    /// cleanup worker and its custody-drop signal until checkout settlement
    /// removes the entry.
    pending_child_teardown: Arc<
        std::sync::Mutex<
            std::collections::HashMap<tidepool_repr::SessionId, Arc<PendingChildTeardown>>,
        >,
    >,
    // The `compile_blocking` span omits `include_roots` from every line (the
    // full search path is long and rarely changes turn to turn); this tracks
    // the last-logged roots per session so a diagnostic reader still sees
    // them once, and again whenever they actually change.
    logged_include_roots:
        std::sync::Mutex<std::collections::HashMap<tidepool_repr::SessionId, String>>,
}

/// One detached cleanup owner for a retired dedicated child session. The
/// worker handle remains here so tests can prove the actual task finished,
/// rather than treating session removal alone as sufficient evidence.
struct PendingChildTeardown {
    wake: Arc<tokio::sync::Notify>,
    #[cfg(test)]
    initial_checkout_complete: std::sync::atomic::AtomicBool,
    #[cfg(test)]
    worker: std::sync::Mutex<Option<tokio::task::JoinHandle<()>>>,
}

impl PendingChildTeardown {
    fn new() -> Self {
        Self {
            wake: Arc::new(tokio::sync::Notify::new()),
            #[cfg(test)]
            initial_checkout_complete: std::sync::atomic::AtomicBool::new(false),
            #[cfg(test)]
            worker: std::sync::Mutex::new(None),
        }
    }
}

fn reject_activation_declaration<H, O>(
    session: &ResidentSession<H, O>,
    scope: ScopeId,
) -> Result<(), ResidentActorWorkbenchError>
where
    H: DispatchEffect<O> + Send,
    O: OutputSink + Sync,
{
    if session
        .current_decl_heads_in(scope)
        .iter()
        .any(|(name, _)| name == "sessionInput")
    {
        return Err(ResidentActorWorkbenchError::InputMount(
            "sessionInput is reserved for activation input; remove its authored declaration before activating".into(),
        ));
    }
    Ok(())
}

struct CancelCompilerTransactionOnDrop(Option<tidepool_runtime::CompilerTransactionCancellation>);

impl Drop for CancelCompilerTransactionOnDrop {
    fn drop(&mut self) {
        if let Some(cancellation) = self.0.take() {
            cancellation.cancel();
        }
    }
}

impl<H, O> ResidentMachineAccess<H, O> {
    fn new(machines: Arc<ActorMachineRegistry<H, O>>, source: ActorWorkbenchSource) -> Self {
        Self {
            machines,
            source,
            handler_effect_support: Arc::new(|_| Vec::new()),
            child_session_factory: None,
            child_bootstrap_program: None,
            image_registry: None,
            child_sessions: Arc::new(std::sync::Mutex::new(std::collections::HashSet::new())),
            pending_child_teardown: Arc::new(std::sync::Mutex::new(
                std::collections::HashMap::new(),
            )),
            logged_include_roots: std::sync::Mutex::new(std::collections::HashMap::new()),
        }
    }

    /// Another entry point into the same machine registry, source, and
    /// carrier cache as `self` — used wherever the runner mints another
    /// workbench or runner for the same actor rather than an independent
    /// one, so a carrier built for one turn serves every later turn instead
    /// of being rebuilt each time a fresh `ResidentActorWorkbench` is
    /// constructed per call.
    fn sharing(&self) -> Self {
        Self {
            machines: Arc::clone(&self.machines),
            source: self.source.clone(),
            handler_effect_support: self.handler_effect_support.clone(),
            child_session_factory: self.child_session_factory.clone(),
            child_bootstrap_program: self.child_bootstrap_program.clone(),
            image_registry: self.image_registry.clone(),
            child_sessions: Arc::clone(&self.child_sessions),
            pending_child_teardown: Arc::clone(&self.pending_child_teardown),
            logged_include_roots: std::sync::Mutex::new(std::collections::HashMap::new()),
        }
    }

    fn owns_pending_child_teardown(
        &self,
        session_id: tidepool_repr::SessionId,
        owner: &Arc<PendingChildTeardown>,
    ) -> bool {
        self.pending_child_teardown
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(&session_id)
            .is_some_and(|current| Arc::ptr_eq(current, owner))
    }

    /// Complete terminal child cleanup under the same membership/owner lock
    /// order as retirement admission. An older worker cannot erase a different
    /// pending owner; terminal checkout settlement may complete the current one.
    fn finish_child_session_teardown(
        &self,
        session_id: tidepool_repr::SessionId,
        expected_owner: Option<&Arc<PendingChildTeardown>>,
    ) -> bool {
        let (removed_child, owner) = {
            let mut children = self
                .child_sessions
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let mut pending = self
                .pending_child_teardown
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if expected_owner.is_some_and(|owner| {
                !pending
                    .get(&session_id)
                    .is_some_and(|current| Arc::ptr_eq(current, owner))
            }) {
                return false;
            }
            (children.remove(&session_id), pending.remove(&session_id))
        };
        if let Some(owner) = &owner {
            owner.wake.notify_one();
        }
        removed_child || owner.is_some()
    }
}

/// Builds a fresh, idle [`ResidentSession`] for a session id the caller has
/// already minted — the composition root's one factory, installed once and
/// called by [`ResidentActorRunner::provision_child_session`] with the child's
/// fixed source layer. `Fn`, not `FnOnce`: called once per eligible child for
/// the life of the host.
pub type ChildSessionFactory<H, O> = Arc<
    dyn Fn(
            tidepool_repr::SessionId,
            &[PathBuf],
            &mut dyn FnMut(tidepool_runtime::CompilerTransactionClose),
        ) -> Result<Box<ResidentSession<H, O>>, String>
        + Send
        + Sync,
>;

/// Keeps an original host binding leased until its consumer accepts or abandons it.
/// Drop schedules retirement through the owning machine checkout.
struct HostInputRetirement {
    input: MountedHostInput,
    _lease: tidepool_runtime::session::resident::BindingLease,
    background_retire: Box<dyn FnOnce() + Send>,
    write: Option<tidepool_runtime::session::PendingHostValueWrite>,
    private: Option<Arc<tidepool_runtime::session::PrivateExecutionAdmission>>,
}

impl HostInputRetirement {
    fn new<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        input: MountedHostInput,
        lease: tidepool_runtime::session::resident::BindingLease,
        write: tidepool_runtime::session::PendingHostValueWrite,
        private: Option<Arc<tidepool_runtime::session::PrivateExecutionAdmission>>,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        let background_retire: Box<dyn FnOnce() + Send> = {
            let machines = Arc::clone(&access.machines);
            let source = access.source.clone();
            let context = context.clone();
            let binder = input.binder.clone();
            Box::new(move || {
                tokio::spawn(async move {
                    let access = ResidentMachineAccess::new(machines, source);
                    if let Err(error) = access
                        .with_machine(context, move |session, ctx, _| {
                            let session_root =
                                carrier_mount_session_root(session, ctx.placement.lexical_scope)?;
                            session.retire_host_binding_owner(&session_root, &binder);
                            Ok(())
                        })
                        .await
                    {
                        tracing::warn!(
                            %error,
                            "failed to retire an abandoned host binding"
                        );
                    }
                });
            })
        };
        Self {
            input,
            _lease: lease,
            background_retire,
            write: Some(write),
            private,
        }
    }

    fn keep_binding(mut self) -> Result<(), ResidentActorWorkbenchError> {
        if let Some(private) = &self.private {
            self.write
                .take()
                .expect("original host mount write")
                .accept(private)
                .map_err(|error| ResidentActorWorkbenchError::Resident(error.into()))?;
        }
        self.background_retire = Box::new(|| {});
        Ok(())
    }

    fn mounted_input(&self) -> &MountedHostInput {
        &self.input
    }
}

/// A named host result whose mount remains guarded until its owned effect step
/// accepts it. The name is presentation; the guard carries exact runtime proof.
pub(crate) struct RetainedHostBinding {
    name: String,
    mounted: Option<HostInputRetirement>,
}

impl RetainedHostBinding {
    pub(crate) fn name(&self) -> &str {
        &self.name
    }

    pub(crate) fn accept(self) -> Result<String, ResidentActorWorkbenchError> {
        if let Some(mounted) = self.mounted {
            mounted.keep_binding()?;
        }
        Ok(self.name)
    }
}

impl Drop for HostInputRetirement {
    fn drop(&mut self) {
        let background = std::mem::replace(&mut self.background_retire, Box::new(|| {}));
        background();
    }
}

/// Owns one invocation's exact parked continuations across machine checkouts.
/// A slot can suspend a nested helper while its earlier hole remains parked,
/// so every created id stays owned until the session reports its retirement.
/// The registration is cloned into blocking checkouts; a late suspension
/// observes abandonment and queues cleanup of only that invocation's ids.
pub(crate) struct ParkedHoleAbortGuard {
    shared: Arc<ParkedHoleAbortState>,
}

struct ParkedHoleAbortState {
    owner: Option<(crate::ActorRef, crate::ActorPlacement)>,
    abort: Arc<dyn Fn(String) + Send + Sync>,
    state: Mutex<ParkedHoleState>,
    reason: String,
    retained_authority: Option<Arc<dyn std::any::Any + Send + Sync>>,
    compiler_owner: std::sync::OnceLock<CompilerCloseOwner>,
}

enum ParkedHoleState {
    Owned(std::collections::BTreeSet<String>),
    Abandoned(std::collections::BTreeSet<String>),
    Settled,
}

impl ParkedHoleAbortGuard {
    fn new<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        cont_id: String,
        reason: String,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        Self::with_latest(access, context, Some(cont_id), reason)
    }

    fn with_latest<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        latest: Option<String>,
        reason: String,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        Self::with_retained_latest(access, context, latest, reason, None)
    }

    fn with_retained_latest<H, O>(
        access: &ResidentMachineAccess<H, O>,
        context: crate::ActorSessionContext,
        latest: Option<String>,
        reason: String,
        retained_authority: Option<Arc<dyn std::any::Any + Send + Sync>>,
    ) -> Self
    where
        H: DispatchEffect<O> + Send + 'static,
        O: OutputSink + Sync + 'static,
    {
        let machines = Arc::clone(&access.machines);
        let source = access.source.clone();
        let cleanup_context = context.clone();
        let cleanup_reason = reason.clone();
        let runtime = tokio::runtime::Handle::current();
        let shared = Arc::new_cyclic(|weak: &std::sync::Weak<ParkedHoleAbortState>| {
            let weak = weak.clone();
            let abort: Arc<dyn Fn(String) + Send + Sync> = Arc::new(move |cont_id| {
                let machines = Arc::clone(&machines);
                let source = source.clone();
                let context = cleanup_context.clone();
                let reason = cleanup_reason.clone();
                let cleanup_id = cont_id.clone();
                let owner = weak.upgrade();
                runtime.spawn(async move {
                    let access = ResidentMachineAccess::new(machines, source);
                    let result = access
                        .with_machine(context, move |session, _, _| {
                            abort_owned_hole(session, cont_id.clone(), reason)
                        })
                        .await;
                    if let Err(error) = result {
                        tracing::warn!(cont_id = %cleanup_id, %error, "failed to abort an abandoned continuation");
                    } else if let Some(owner) = owner {
                        ParkedHoleAbortRegistration(owner)
                            .observe(ResidentContinuationEvent::Retired(cleanup_id));
                    }
                });
            });
            ParkedHoleAbortState {
                owner: Some((context.actor, context.placement)),
                abort,
                state: Mutex::new(ParkedHoleState::Owned(latest.into_iter().collect())),
                reason,
                retained_authority,
                compiler_owner: std::sync::OnceLock::new(),
            }
        });
        Self { shared }
    }

    pub(crate) fn with_compiler_owner(self, owner: CompilerCloseOwner) -> Self {
        assert!(
            self.shared.compiler_owner.set(owner).is_ok(),
            "cleanup owner is assigned once before native admission"
        );
        self
    }

    pub(crate) fn registration(&self) -> ParkedHoleAbortRegistration {
        ParkedHoleAbortRegistration(Arc::clone(&self.shared))
    }

    /// The owning checkout is in hand: the hole's fate is now decided
    /// synchronously within it, so no background cleanup is needed.
    pub(crate) fn disarm(self) {
        let mut state = self.shared.state.lock();
        *state = ParkedHoleState::Settled;
        drop(state);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContinuationHandoffFailure {
    WrongOwner,
    Abandoned,
    Settled,
    NotOwned,
}

impl Drop for ParkedHoleAbortGuard {
    fn drop(&mut self) {
        let abandoned = {
            let mut state = self.shared.state.lock();
            match std::mem::replace(&mut *state, ParkedHoleState::Settled) {
                ParkedHoleState::Owned(current) => {
                    *state = ParkedHoleState::Abandoned(current.clone());
                    current
                }
                ParkedHoleState::Abandoned(current) => {
                    *state = ParkedHoleState::Abandoned(current);
                    std::collections::BTreeSet::new()
                }
                ParkedHoleState::Settled => std::collections::BTreeSet::new(),
            }
        };
        for cont_id in abandoned {
            (self.shared.abort)(cont_id);
        }
    }
}

pub(crate) struct ParkedHoleAbortRegistration(Arc<ParkedHoleAbortState>);

impl Clone for ParkedHoleAbortRegistration {
    fn clone(&self) -> Self {
        Self(Arc::clone(&self.0))
    }
}

impl ParkedHoleAbortRegistration {
    fn abandon_for_acknowledgement(
        &self,
        context: &crate::ActorSessionContext,
    ) -> Result<(), ResidentActorWorkbenchError> {
        let owner_matches = self.0.owner.is_some_and(|(actor, placement)| {
            actor == context.actor && placement == context.placement
        });
        let private_matches = self
            .0
            .retained_authority
            .as_ref()
            .and_then(|authority| {
                authority.downcast_ref::<crate::resident_actor::ExecutionResourceOwners>()
            })
            .is_some_and(|resources| resources.authorizes_cleanup_context(context));
        if !owner_matches && !private_matches {
            return Err(ResidentActorWorkbenchError::ActorProtocol(
                "continuation cleanup differs from its admitted actor placement".into(),
            ));
        }
        let mut state = self.0.state.lock();
        if let ParkedHoleState::Owned(current) = &mut *state {
            *state = ParkedHoleState::Abandoned(std::mem::take(current));
        }
        Ok(())
    }

    fn awaiting_acknowledgement(&self) -> Vec<String> {
        match &*self.0.state.lock() {
            ParkedHoleState::Owned(current) | ParkedHoleState::Abandoned(current) => {
                current.iter().cloned().collect()
            }
            ParkedHoleState::Settled => Vec::new(),
        }
    }

    fn confirm_acknowledgement_in_checkout(&self) -> Result<(), ResidentActorWorkbenchError> {
        let mut state = self.0.state.lock();
        match &*state {
            ParkedHoleState::Owned(current) | ParkedHoleState::Abandoned(current)
                if !current.is_empty() =>
            {
                Err(ResidentActorWorkbenchError::ActorProtocol(
                    "native continuation cleanup remains unconfirmed".into(),
                ))
            }
            _ => {
                *state = ParkedHoleState::Owned(Default::default());
                Ok(())
            }
        }
    }

    pub(crate) async fn scope<F: std::future::Future>(&self, operation: F) -> F::Output {
        let compiler_owner = self.0.compiler_owner.get().cloned();
        let scoped = SLOT_CONTINUATION_OWNER.scope(self.clone(), operation);
        match compiler_owner {
            Some(owner) => owner.scope(scoped).await,
            None => scoped.await,
        }
    }

    pub(crate) fn sync_scope<T>(&self, operation: impl FnOnce() -> T) -> T {
        let compiler_owner = self.0.compiler_owner.get().cloned();
        match compiler_owner {
            Some(owner) => COMPILER_CLOSE_OWNER.sync_scope(owner, || {
                SLOT_CONTINUATION_OWNER.sync_scope(self.clone(), operation)
            }),
            None => SLOT_CONTINUATION_OWNER.sync_scope(self.clone(), operation),
        }
    }

    fn observe(&self, event: ResidentContinuationEvent) {
        let abort = {
            let mut state = self.0.state.lock();
            match event {
                ResidentContinuationEvent::Parked(cont_id) => match &mut *state {
                    ParkedHoleState::Owned(current) => {
                        current.insert(cont_id);
                        None
                    }
                    ParkedHoleState::Abandoned(current) => {
                        current.insert(cont_id.clone()).then_some(cont_id)
                    }
                    ParkedHoleState::Settled => None,
                },
                ResidentContinuationEvent::Retired(cont_id) => {
                    match &mut *state {
                        ParkedHoleState::Owned(current) | ParkedHoleState::Abandoned(current) => {
                            current.remove(&cont_id);
                        }
                        ParkedHoleState::Settled => {}
                    }
                    None
                }
            }
        };
        if let Some(cont_id) = abort {
            (self.0.abort)(cont_id);
        }
    }

    /// Transfer ownership to the exact continuation returned by this
    /// checkout. If the async owner was dropped while the blocking operation
    /// ran, settle the late successor before releasing the checked-out
    /// session.
    fn replace_in_checkout<H, O>(
        &self,
        session: &mut ResidentSession<H, O>,
        outcome: &ResidentOutcome,
    ) where
        H: DispatchEffect<O> + Send,
        O: OutputSink + Sync,
    {
        let successor = outcome_continuation_id(outcome);
        let abandoned = {
            let mut state = self.0.state.lock();
            match std::mem::replace(&mut *state, ParkedHoleState::Settled) {
                ParkedHoleState::Abandoned(_) => {
                    *state = ParkedHoleState::Abandoned(successor.clone().into_iter().collect());
                    true
                }
                ParkedHoleState::Owned(_) => {
                    *state = successor
                        .clone()
                        .map_or(ParkedHoleState::Settled, |cont_id| {
                            ParkedHoleState::Owned(std::iter::once(cont_id).collect())
                        });
                    false
                }
                ParkedHoleState::Settled => false,
            }
        };
        if abandoned {
            let reason = self.0.reason.clone();
            if let Some(cont_id) = successor {
                if let Err(error) = abort_owned_hole(session, cont_id.clone(), reason) {
                    tracing::warn!(%cont_id, %error, "failed to abort a late continuation after its owner was dropped");
                    (self.0.abort)(cont_id);
                } else {
                    self.observe(ResidentContinuationEvent::Retired(cont_id));
                }
            }
        }
    }
}

fn outcome_continuation_id(outcome: &ResidentOutcome) -> Option<String> {
    match outcome {
        ResidentOutcome::Suspended { hole, .. } | ResidentOutcome::Deferred { hole, .. } => {
            Some(hole.cont_id().to_owned())
        }
        ResidentOutcome::Completed { .. } | ResidentOutcome::BindingsCommitted { .. } => None,
    }
}

fn abort_owned_hole<H, O>(
    session: &mut ResidentSession<H, O>,
    cont_id: String,
    reason: String,
) -> Result<(), ResidentActorWorkbenchError>
where
    H: DispatchEffect<O> + Send,
    O: OutputSink + Sync,
{
    if !session.parked_holes().contains(&cont_id.as_str()) {
        return Ok(());
    }
    let outcome = session.abort(&cont_id, reason);
    if !session.parked_holes().contains(&cont_id.as_str()) {
        return Ok(());
    }
    match outcome {
        Err(error) => Err(ResidentActorWorkbenchError::Resident(error)),
        Ok(_) => Err(ResidentActorWorkbenchError::ActorProtocol(format!(
            "aborting continuation {cont_id} left it parked"
        ))),
    }
}

