enum OwnedHostPayload {
    Json(serde_json::Value),
    Text(String),
    Job(String),
}

/// Live execution state for one workbench item that suspended on an actor
/// effect. The continuation and any value it binds remain owned by the
/// actor's resource scope; this value only carries the item-local rendering
/// state needed while the actor interpreter settles nominal effects.
pub(crate) struct ResidentWorkbenchFragment {
    display: WorkbenchDisplay,
    output: Vec<String>,
    presented: Vec<String>,
    recovered_jobs: Vec<String>,
    warnings: Vec<String>,
    /// Job ids returned by `Cmd.start` effects resolved while this exact
    /// item's Haskell computation was running. A single unambiguous job here
    /// against a single command-job-typed binder in `display` identifies
    /// the authored job binding — see
    /// `settle_fragment`'s tagging of `host_text_bindings` on completion.
    started_jobs: Vec<String>,
}

impl ResidentWorkbenchFragment {
    #[cfg(test)]
    pub(crate) fn empty_for_test() -> Self {
        Self {
            display: WorkbenchDisplay::Discard,
            output: Vec::new(),
            presented: Vec::new(),
            recovered_jobs: Vec::new(),
            warnings: Vec::new(),
            started_jobs: Vec::new(),
        }
    }

    pub(crate) fn summarizes_bound_commands(&self) -> bool {
        matches!(
            &self.display,
            WorkbenchDisplay::Binding {
                captured: false,
                ..
            }
        )
    }

    pub(crate) fn retain_job_binding(&mut self, binding: String) {
        self.recovered_jobs.push(binding);
    }

    pub(crate) fn recovered_bindings(&self) -> &[String] {
        &self.recovered_jobs
    }

    /// Record that a `Cmd.start` effect resolved to this job id while this
    /// item's computation was running. Only tagged onto a binding at
    /// completion when it is the item's sole started job and its sole
    /// command-job-typed binder — see `settle_fragment`.
    pub(crate) fn record_started_job(&mut self, job: String) {
        self.started_jobs.push(job);
    }

    /// Charge streamed output and explicit display pages to the same
    /// allowance. Transport limits count bytes; Haskell tree limits count chars.
    pub(crate) fn present_output(&mut self, text: &str, remaining: &mut usize) -> String {
        let text = crate::workbench_display::bounded_output(text, *remaining);
        *remaining = remaining.saturating_sub(text.len() + 1);
        text
    }

    pub(crate) fn present_command(
        &mut self,
        job: String,
        presentation: tidepool_bridge_effects::CommandPresentation,
        remaining: &mut usize,
    ) -> String {
        if !self.presented.contains(&job) {
            self.presented.push(job);
        }
        if let tidepool_bridge_effects::CommandPresentation::CommandVisible(text, _) = presentation
        {
            self.present_output(&text, remaining)
        } else {
            String::new()
        }
    }
}

/// Programmatic actor tool response. It carries the authored semantic value
/// without requiring a host presentation.
#[derive(Debug, serde::Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
pub enum ToolDispatchReply {
    Success {
        output: serde_json::Value,
    },
    Refused {
        #[serde(flatten)]
        error: ToolDispatchError,
    },
}

#[derive(Debug, serde::Deserialize, serde::Serialize, thiserror::Error)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum ToolDispatchError {
    #[error("{error}")]
    UnknownTool {
        #[serde(skip_serializing)]
        error: String,
        tool: String,
    },
    #[error("{error}")]
    InvalidInput {
        #[serde(skip_serializing)]
        error: String,
        tool: String,
        detail: String,
    },
}

impl ToolDispatchReply {
    pub fn into_output(self) -> Result<serde_json::Value, ToolDispatchError> {
        match self {
            Self::Success { output } => Ok(output),
            Self::Refused { error } => Err(error),
        }
    }
}

/// Installed named-tool envelope. The host receives semantic output and a
/// separately selected presentation; refusal remains a distinct variant.
#[derive(Debug, serde::Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
enum InstalledToolDispatchReply {
    Success {
        output: serde_json::Value,
        presentation: String,
    },
    Refused {
        #[serde(flatten)]
        error: ToolDispatchError,
    },
}

impl InstalledToolDispatchReply {
    fn into_parts(self) -> Result<(serde_json::Value, String), ToolDispatchError> {
        match self {
            Self::Success {
                output,
                presentation,
            } => Ok((output, presentation)),
            Self::Refused { error } => Err(error),
        }
    }
}

/// Decode the dispatcher result after the handler has completed. A malformed
/// success envelope is an uncertain post-execution failure; only an explicit
/// typed refusal maps to the pre-execution refusal variant.
fn decode_tool_dispatch_reply(
    text: &str,
) -> Result<InstalledToolDispatchReply, ResidentActorWorkbenchError> {
    serde_json::from_str(text).map_err(|error| {
        ResidentActorWorkbenchError::ActorProtocol(format!("invalid tool dispatch reply: {error}"))
    })
}
impl ToolDispatchError {
    pub fn tool(&self) -> &str {
        match self {
            Self::UnknownTool { tool, .. } | Self::InvalidInput { tool, .. } => tool,
        }
    }
}

enum WorkbenchDisplay {
    Binding {
        binders: Vec<BoundBinder>,
        // Captured bare results retain a thunk and do not summarize authored commands.
        captured: bool,
    },
    Discard,
    Tool,
    ToolDispatch,
}

/// One typed response obligation and the request identity it belongs to.
#[derive(Clone)]
pub struct RequestWorkbenchScope {
    pub response: ResponseExpectation,
    pub request: crate::RequestId,
}

impl ActorWorkbenchSource {
    fn for_activation(mut self, context: &crate::ActorSessionContext) -> Self {
        // Pure activation previews consume native input; authored
        // reply helpers belong to subsequent request workbench cells.
        self.request_helper_recipe =
            tidepool_toolchain::declaration_join::RequestHelperRecipe::None;
        self.for_workbench(context, None)
    }

    fn for_workbench(
        mut self,
        context: &crate::ActorSessionContext,
        request_scope: Option<&RequestWorkbenchScope>,
    ) -> Self {
        if let Some(scope) = request_scope {
            self.request_helper_recipe =
                tidepool_toolchain::declaration_join::RequestHelperRecipe::ActorReply;
            self.preamble = self
                .request_preamble(scope.request, context.haskell_effects_alias.expression())
                .into();
        }
        self.preamble = actor_preamble(&self.preamble, context).into();
        self
    }
}

