/// A fragment has already collected its output before returning a parked frame.
/// Completion belongs to the settled step; external work remains owned here
/// until the same continuation is dispatched or aborted.
pub(crate) enum ResidentWorkbenchSuspension {
    Ask {
        hole: ResidentHole,
        request: HaskellValue,
    },
    Deferred {
        hole: ResidentHole,
        request: HaskellValue,
        work: tidepool_effect::DeferredEffect,
    },
}

#[cfg(test)]
impl ResidentWorkbenchSuspension {
    fn continuation_id(&self) -> &str {
        match self {
            Self::Ask { hole, .. } | Self::Deferred { hole, .. } => hole.cont_id(),
        }
    }
}

impl From<ResidentWorkbenchSuspension> for ResidentOutcome {
    fn from(suspension: ResidentWorkbenchSuspension) -> Self {
        match suspension {
            ResidentWorkbenchSuspension::Ask { hole, request } => Self::Suspended {
                output: Vec::new(),
                hole,
                request,
            },
            ResidentWorkbenchSuspension::Deferred {
                hole,
                request,
                work,
            } => Self::Deferred {
                output: Vec::new(),
                hole,
                request,
                work,
            },
        }
    }
}

fn tool_installation_request<H, O>(
    session: &mut ResidentSession<H, O>,
    registration: &ParkedHoleAbortRegistration,
    suspension: ResidentWorkbenchSuspension,
) -> Result<(ResidentHole, HaskellValue), ResidentActorWorkbenchError>
where
    H: DispatchEffect<O> + Send,
    O: OutputSink + Sync,
{
    match suspension {
        ResidentWorkbenchSuspension::Ask { hole, request } => Ok((hole, request)),
        ResidentWorkbenchSuspension::Deferred { hole, work, .. } => {
            let reason = "tool installer crossed an external effect boundary before publication";
            match session.abort(hole.cont_id(), reason.into()) {
                Ok(settled) => registration.replace_in_checkout(session, &settled),
                Err(abort_error) => tracing::warn!(
                    hole = hole.cont_id(),
                    %abort_error,
                    "failed to abort deferred tool installation"
                ),
            }
            drop(work);
            Err(ResidentActorWorkbenchError::ActorProtocol(reason.into()))
        }
    }
}

fn capture_request_receiver_entry<H, O>(
    session: &mut ResidentSession<H, O>,
    hole: &ResidentHole,
    site: i64,
    actor_realm: RealmId,
) -> Result<RootCustody, ResidentActorWorkbenchError>
where
    H: DispatchEffect<O> + Send,
    O: OutputSink + Sync,
{
    let site = u64::try_from(site).map_err(|_| {
        ResidentActorWorkbenchError::ActorProtocol(
            "request receiver registration carried an invalid site id".into(),
        )
    })?;
    if session.parked_realm(hole) != Some(actor_realm) {
        return Err(ResidentActorWorkbenchError::ActorProtocol(
            "request receiver registration escaped its actor realm".into(),
        ));
    }
    if !session
        .parked_program_provenance(hole)
        .is_some_and(|provenance| provenance.has_completion_site(site))
    {
        return Err(ResidentActorWorkbenchError::ActorProtocol(
            format!("request receiver registration has no compiler-issued completion site: requested {site}"),
        ));
    }
    session
        .live_payload_handle_owned_by(hole.cont_id(), actor_realm)?
        .ok_or_else(|| {
            ResidentActorWorkbenchError::ActorProtocol(
                "request receiver registration has no live entry".into(),
            )
        })
}

fn require_tool_installation_completion<H, O>(
    session: &mut ResidentSession<H, O>,
    registration: &ParkedHoleAbortRegistration,
    settled: &ResidentOutcome,
) -> Result<(), ResidentActorWorkbenchError>
where
    H: DispatchEffect<O> + Send,
    O: OutputSink + Sync,
{
    if let Some(cont_id) = outcome_continuation_id(settled) {
        match session.abort(
            &cont_id,
            "tool installer must finish after publication".into(),
        ) {
            Ok(outcome) => registration.replace_in_checkout(session, &outcome),
            Err(abort_error) => tracing::warn!(
                hole = cont_id,
                %abort_error,
                "failed to abort parked hole after tool installer overrun"
            ),
        }
        return Err(ResidentActorWorkbenchError::ActorProtocol(
            "tool installer did not finish after publication".into(),
        ));
    }
    Ok(())
}

/// The one machine-entry component for installed actor program segments.
/// It shares checkout/context installation with the fenced workbench; startup
/// and later mailbox scheduling therefore cannot grow a second dispatcher.
pub struct ResidentActorRunner<H, O> {
    access: ResidentMachineAccess<H, O>,
}

/// Preparation owns a fresh session until an exact actor takes custody. The
/// runner's existing synchronous discard operation also covers a dropped await.
/// Shared preparation custody keeps refusal cleanup ahead of discard;
/// admission disarms every share when the actor takes ownership.
#[derive(Clone)]
pub(crate) struct ChildSessionStartupLease {
    custody: Arc<ChildSessionStartupCustody>,
}

struct ChildSessionStartupCustody {
    discard: parking_lot::Mutex<Option<Box<dyn FnOnce() + Send + Sync>>>,
}

impl ChildSessionStartupLease {
    pub(crate) fn admitted(self) {
        self.custody.discard.lock().take();
    }
}

impl Drop for ChildSessionStartupCustody {
    fn drop(&mut self) {
        if let Some(discard) = self.discard.get_mut().take() {
            discard();
        }
    }
}

