    async fn authored_cell_requires_both_source_and_private_execution_admission_with_compiler_owner(
    ) {
        let (machines, context, source, _root) = actor_registry_fixture();
        let workbench = ResidentActorWorkbench::new(machines, source, None)
            .with_json_input(Some(serde_json::json!(42)));
        let scope = crate::call_timing::CallScope::new(
            "cell",
            context.actor.id.0,
            context.actor.incarnation.0,
        );
        let Err(error) = scope
            .run(workbench.prepare_cell(context.clone(), "let x = (42 :: Int)".into()))
            .await
        else {
            panic!("unadmitted authored cell compiled")
        };
        assert!(matches!(
            error,
            ResidentActorWorkbenchError::ActorProtocol(_)
        ));
        assert_eq!(
            scope.compile_count(),
            0,
            "refusal precedes input mounting and compilation"
        );
        let workbench = workbench.with_compilation_authority(
            crate::resident_actor::WorkbenchCompilationAuthority::for_test(context.clone()),
        );
        let Err(error) = scope
            .run(workbench.prepare_cell(context, "let x = (42 :: Int)".into()))
            .await
        else {
            panic!("source authority automatically granted private execution")
        };
        assert!(matches!(
            error,
            ResidentActorWorkbenchError::ActorProtocol(_)
        ));
        assert_eq!(scope.compile_count(), 0);
    }

    #[tokio::test]
    async fn planned_cell_refuses_changed_own_scope_but_ignores_sibling_and_child_commits() {
        with_test_compiler_owner(planned_cell_refuses_changed_own_scope_but_ignores_sibling_and_child_commits_with_compiler_owner()).await;
    }

    async fn planned_cell_refuses_changed_own_scope_but_ignores_sibling_and_child_commits_with_compiler_owner(
    ) {
        for mutate_own in [false, true] {
            let (machines, context, source, _root) = actor_registry_fixture();
            let initial = ResidentActorWorkbench::new(Arc::clone(&machines), source.clone(), None);
            let (initial, private_context) = initial
                .admit_private_cell_for_test(context.clone())
                .await
                .unwrap();
            initial
                .execute_cell_for_test(private_context.clone(), "ownValue <- pure (41 :: Int)")
                .await
                .unwrap();
            initial
                .publish_completed_cell_for_test(private_context)
                .await
                .unwrap();
            let workbench =
                ResidentActorWorkbench::new(Arc::clone(&machines), source.clone(), None);
            let (workbench, context) = workbench
                .admit_private_cell_for_test(context)
                .await
                .unwrap();
            let (sibling, child) = workbench
                .access
                .with_machine(context.clone(), |session, context, _| {
                    Ok((
                        session.mint_isolated_scope(),
                        session
                            .mint_scope(context.placement.lexical_scope)
                            .expect("fork scope"),
                    ))
                })
                .await
                .unwrap();
            let probe = Arc::new(split_probe::SplitProbe {
                held_installs: 1,
                ..Default::default()
            });
            let prepare = split_probe::PROBE.scope(
                probe.clone(),
                workbench.prepare_cell(context.clone(), "derived <- pure (ownValue + 1)".into()),
            );
            tokio::pin!(prepare);
            tokio::select! {
                result = &mut prepare => match result {
                    Err(error) => panic!("checked preparation refused before the race barrier: {error}"),
                    Ok(_) => panic!("checked preparation skipped the race barrier"),
                },
                _ = probe.install_reached.notified() => {}
            }
            if mutate_own {
                workbench
                    .execute_cell_for_test(context.clone(), "laterValue <- pure (42 :: Int)")
                    .await
                    .expect("checked execution changes the admitted scope");
            } else {
                for scope in [sibling, child] {
                    let mut changing = context.clone();
                    changing.placement.lexical_scope = scope;
                    let changing_workbench =
                        ResidentActorWorkbench::new(Arc::clone(&machines), source.clone(), None);
                    let (changing_workbench, private_context) = changing_workbench
                        .admit_private_cell_for_test(changing)
                        .await
                        .unwrap();
                    changing_workbench
                        .execute_cell_for_test(
                            private_context.clone(),
                            "laterValue <- pure (42 :: Int)",
                        )
                        .await
                        .unwrap();
                    changing_workbench
                        .publish_completed_cell_for_test(private_context)
                        .await
                        .expect("checked publication changes only its sibling or child scope");
                }
            }
            probe.resume_install.notify_one();
            let result = prepare.await;
            if mutate_own {
                assert!(matches!(
                    result,
                    Err(ResidentActorWorkbenchError::Resident(
                        ResidentError::Session(
                            tidepool_runtime::session::SessionError::StaleStagedDeclaration
                        )
                    ))
                ));
            } else {
                let (_, prepared) =
                    result.expect("unrelated scopes leave the admitted program current");
                assert_eq!(prepared.items.len(), 1);
            }
            workbench
                .access
                .with_machine(context, |session, context, _| {
                    assert!(
                        session
                            .current_binding_in(context.placement.lexical_scope, "derived")
                            .is_none(),
                        "preparation cannot execute or publish a planned item"
                    );
                    Ok(())
                })
                .await
                .unwrap();
        }
    }

