    #[tokio::test]
    async fn installed_effect_imports_reach_lookup_and_batched_type_queries() {
        with_test_compiler_owner(async {
            let (machines, mut context, source, _root) = actor_lookup_registry_fixture();
            let installation = crate::agent_spec::installation_expression("Fixture.agentSpec", &[
                crate::ActorEffectKey::Watches, crate::ActorEffectKey::Replies,
                crate::ActorEffectKey::AgentLaunch,
            ]);
            context.haskell_effects_alias = installation.dispatcher_effect_row();
            let preamble = format!(
                "{}\nmodule Expr where\nimport Prelude\nimport qualified Tidepool.Agent.Watch as PublicWatch\nimport qualified Tidepool.Agent.Reply as PublicReply\nimport Tidepool.Actors.Spawn (checkpoint, spawnSubagent)\n{}",
                tidepool_runtime::session::EVAL_PRAGMAS,
                tidepool_runtime::session::PREAMBLE_IMPORT_MARKER,
            );
            assert!(!preamble.contains("import qualified Tidepool.Agent.Watch.Internal"));
            assert!(!preamble.contains("import qualified Tidepool.Agent.Reply.Internal"));
            let source = ActorWorkbenchSource::new(preamble.clone(), source.base_include.to_vec());
            let workbench = ResidentActorWorkbench::new(machines, source.clone(), None);
            let (view, inputs, prepared) = workbench.access.with_machine(context.clone(), move |session, context, _| {
                let view = actor_compile_view(session, context, &source)?;
                let inputs = session.capture_inspection_inputs(view.session_view())
                    .map_err(|error| ResidentActorWorkbenchError::Resident(ResidentError::Session(error)))?;
                let prepared = source.prepare(&view);
                Ok((view, inputs, prepared))
            }).await.unwrap();
            let names = ["checkpoint", "spawnSubagent"];
            let structured_query = |name: &str| tidepool_runtime::session::NameQuery {
                scope: tidepool_runtime::session::NameScope::Current,
                namespace: tidepool_runtime::session::NameNamespace::Value,
                name: name.into(),
            };
            let provenance = tidepool_runtime::session::ScopeProvenance {
                scope: tidepool_runtime::session::NameScope::Current,
                generation: 1,
                fingerprint: "installed-effect-row-test".into(),
            };
            for queries in [
                names.map(|name| InspectionQuery::Info(name.into())).to_vec(),
                names.map(|name| InspectionQuery::TypeOf(name.into())).to_vec(),
                names.map(|name| InspectionQuery::StructuredInfo {
                    query: structured_query(name), provenance: provenance.clone(),
                }).to_vec(),
                names.map(|name| InspectionQuery::StructuredType {
                    query: structured_query(name), provenance: provenance.clone(),
                }).to_vec(),
            ] {
                let answers = tidepool_testing::with_settlement(|settlement| inspect_lookup_queries(&view, Some(&inputs), &prepared.preamble,
                    &prepared.imports, &prepared.include, &prepared.injected,
                    &context.haskell_effects_alias, &queries, None, settlement)).unwrap();
                assert_eq!(answers.len(), 2);
                assert!(answers.iter().all(|answer| matches!(answer,
                    tidepool_runtime::session::InspectionResult::Info { .. }
                    | tidepool_runtime::session::InspectionResult::Type { .. }
                    | tidepool_runtime::session::InspectionResult::StructuredInfo(Ok(_))
                    | tidepool_runtime::session::InspectionResult::StructuredType(Ok(_)))), "{answers:#?}");
                for (answer, name) in answers.iter().zip(names) {
                    match answer {
                        tidepool_runtime::session::InspectionResult::StructuredInfo(Ok(info)) => {
                            assert_eq!(info.identifier.name, name);
                            assert_eq!(info.provenance, provenance);
                        }
                        tidepool_runtime::session::InspectionResult::StructuredType(Ok(info)) => {
                            assert_eq!(info.identifier.name, name);
                            assert_eq!(info.provenance, provenance);
                        }
                        _ => {}
                    }
                }
            }
            // Drop only the issued import component, matching the old boundary.
            // The receiving compiler must reject these unresolved nominal names.
            let uncoupled = tidepool_runtime::session::HaskellTypeSource::from(
                context.haskell_effects_alias.expression());
            let include = prepared.include.iter().map(PathBuf::as_path).collect::<Vec<_>>();
            let rejected = tidepool_testing::with_settlement(|settlement| run_inspections(InspectionRequest {
                exact_context: None, preamble: &preamble, imports: "", include: &include,
                session_root: view.session_root(), inject_modules: &[],
                queries: &[InspectionQuery::Info("checkpoint".into())], effects: Some(&uncoupled),
            }, settlement)).unwrap();
            assert!(matches!(&rejected[..], [tidepool_runtime::session::InspectionResult::Rejected { .. }]));
            if let tidepool_runtime::session::InspectionResult::Rejected { diagnostic } = &rejected[0] {
                assert!(diagnostic.contains("Tidepool.Agent.Watch.Internal.Watches"));
                assert!(diagnostic.contains("Tidepool.Agent.Reply.Internal.Replies"));
            }
            // Standalone inspection carries no actor row and remains legitimate.
            let standalone = tidepool_testing::with_settlement(|settlement| run_inspections(InspectionRequest {
                exact_context: None, preamble: &preamble, imports: "", include: &include,
                session_root: view.session_root(), inject_modules: &[],
                queries: &[InspectionQuery::Info("checkpoint".into())], effects: None,
            }, settlement)).unwrap();
            assert!(matches!(&standalone[..], [tidepool_runtime::session::InspectionResult::Info { .. }]));
        }).await;
    }

    #[tokio::test]
    async fn lookup_batches_qualified_export_facts_in_one_compiler_request() {
        with_test_compiler_owner(
            lookup_batches_qualified_export_facts_in_one_compiler_request_with_compiler_owner(),
        )
        .await;
    }

    async fn lookup_batches_qualified_export_facts_in_one_compiler_request_with_compiler_owner() {
        use crate::lookup::LookupOutcome;
        use std::cell::{Cell, RefCell};

        let (machines, mut context, source, _root) = actor_lookup_registry_fixture();
        let installation = crate::agent_spec::installation_expression(
            "Fixture.agentSpec",
            &[
                crate::ActorEffectKey::Replies,
                crate::ActorEffectKey::Watches,
                crate::ActorEffectKey::Notifications,
                crate::ActorEffectKey::Sleep,
                crate::ActorEffectKey::Lookup,
            ],
        );
        // The inspector must compile the same checked effect row as installation,
        // then retain its typed identity for availability decisions.
        context.haskell_effects_alias = installation.dispatcher_effect_row();
        let modules = tempfile::tempdir().expect("lookup source fixtures");
        std::fs::create_dir(modules.path().join("LookupPlanParent")).unwrap();
        for (path, bytes) in [
            (
                "LookupPlanParent.hs",
                &tidepool_testing::fixture_source(
                    "exomonad/actor/src/fixtures/LookupPlanParent.hs",
                ),
            ),
            (
                "LookupPlanParent/Choice.hs",
                &tidepool_testing::fixture_source(
                    "exomonad/actor/src/fixtures/LookupPlanChoice.hs",
                ),
            ),
            (
                "LookupPlanParent/ModuleOnly.hs",
                &tidepool_testing::fixture_source(
                    "exomonad/actor/src/fixtures/LookupPlanModuleOnly.hs",
                ),
            ),
        ] {
            std::fs::write(modules.path().join(path), bytes).unwrap();
        }
        // Aliases deliberately leave the original qualified constructor name
        // outside reader scope. Its parent export browse must still resolve it.
        let preamble = insert_preamble_imports(&source.preamble,
            "qualified LookupPlanParent as Parent\nqualified LookupPlanParent.Choice as Child\nqualified LookupPlanParent.ModuleOnly as ModuleOnly");
        let mut include = source.base_include.to_vec();
        include.push(modules.path().to_owned());
        let source = ActorWorkbenchSource::new(preamble, include);
        let workbench = ResidentActorWorkbench::new(machines, source.clone(), None);
        let (view, inputs, prepared) = workbench
            .access
            .with_machine(context.clone(), move |session, context, _| {
                let view = actor_compile_view(session, context, &source)?;
                let inputs = session
                    .capture_inspection_inputs(view.session_view())
                    .map_err(|error| {
                        ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                    })?;
                let prepared = source.prepare(&view);
                Ok((view, inputs, prepared))
            })
            .await
            .expect("lookup view captures");
        let trace = lookup_trace_path();
        let before = compiler_trace_started_ids(&trace);
        let calls = Cell::new(0);
        let inspected = RefCell::new(None);
        let answer = crate::lookup::execute(
            real_lookup_request(vec![
                "LookupPlanParent.ModuleOnly".into(),
                "LookupPlanParent.Choice".into(),
                "LookupPlanParent.ConstructorOnly".into(),
                "LookupApi.lookupRaw".into(),
                "doc workbench".into(),
            ]),
            "view".into(),
            &prepared.imports,
            &prepared.injected,
            &[],
            crate::UsagePointerTable::default(),
            |queries| {
                calls.set(calls.get() + 1);
                let result = tidepool_testing::with_settlement(|settlement| {
                    inspect_lookup_queries(
                        &view,
                        Some(&inputs),
                        &prepared.preamble,
                        &prepared.imports,
                        &prepared.include,
                        &prepared.injected,
                        &context.haskell_effects_alias,
                        queries,
                        None,
                        settlement,
                    )
                })?;
                *inspected.borrow_mut() = Some(result.clone());
                Ok(result)
            },
        );
        assert_eq!(
            calls.get(),
            1,
            "one compiler submission supplies known facts"
        );
        let after = compiler_trace_started_ids(&trace);
        assert_eq!(
            after.difference(&before).count(),
            1,
            "successful module/name/doc batch must execute exactly one real worker request"
        );
        assert!(answer.issue.is_none(), "typed row witness must compile");
        let inspected = inspected.into_inner().expect("lookup inspections");
        let lookup = inspected
            .iter()
            .find_map(|result| match result {
                tidepool_runtime::session::InspectionResult::Info { entries, .. } => {
                    entries.iter().find(|entry| entry.name == "lookupRaw")
                }
                _ => None,
            })
            .expect("lookupRaw inspection");
        assert_eq!(
            lookup.availability,
            tidepool_runtime::session::InspectionAvailability::Available,
            "availability must use the exact installed effect row"
        );
        assert!(
            matches!(&answer.results[0].outcome, LookupOutcome::Found(entries, false) if entries.len() == 1),
            "module exports remain available"
        );
        assert!(
            matches!(&answer.results[1].outcome, LookupOutcome::Ambiguous(entries, false) if entries.len() == 2),
            "parent type/constructor ambiguity wins over a same-named module"
        );
        assert!(
            matches!(&answer.results[2].outcome, LookupOutcome::Found(entries, false) if entries.len() == 1),
            "qualified constructor resolves outside the imported alias"
        );
        assert!(
            matches!(&answer.results[3].outcome, LookupOutcome::Found(entries, false) if entries.len() == 1),
            "lookup effect declaration resolves in the installed row"
        );
        assert!(
            matches!(&answer.results[4].outcome, LookupOutcome::Found(entries, false) if entries.len() == 1),
            "documentation resolves alongside compiler queries"
        );
        let before_docs = compiler_trace_started_ids(&trace);
        let docs = crate::lookup::execute(
            real_lookup_request(vec!["doc workbench".into()]),
            "view".into(),
            &prepared.imports,
            &prepared.injected,
            &[],
            crate::UsagePointerTable::default(),
            |_| panic!("documentation-only lookup must not submit to the compiler"),
        );
        assert!(matches!(
            &docs.results[0].outcome,
            LookupOutcome::Found(_, false)
        ));
        assert_eq!(compiler_trace_started_ids(&trace), before_docs);
    }

    #[tokio::test]
    async fn lookup_inspects_checked_bound_value_on_repeated_requests() {
        with_test_compiler_owner(
            lookup_inspects_checked_bound_value_on_repeated_requests_with_compiler_owner(),
        )
        .await;
    }

    async fn lookup_inspects_checked_bound_value_on_repeated_requests_with_compiler_owner() {
        let (machines, context, source, _root) = actor_lookup_registry_fixture();
        let workbench = ResidentActorWorkbench::new(Arc::clone(&machines), source.clone(), None);
        let mut sibling_context = context.clone();
        sibling_context.placement.lexical_scope = workbench
            .access
            .with_machine(context.clone(), |session, _, _| {
                Ok(session.mint_isolated_scope())
            })
            .await
            .expect("private sibling scope");
        sibling_context.actor = crate::ActorRef::first(crate::ActorId(2));
        let mut checked_workbenches = Vec::new();
        for public_context in [context, sibling_context] {
            let public_scope = public_context.placement.lexical_scope;
            let checked_workbench =
                ResidentActorWorkbench::new(Arc::clone(&machines), source.clone(), None);
            let (checked_workbench, private_context) = checked_workbench
                .admit_private_cell_for_test(public_context)
                .await
                .expect("private execution admission");
            assert_ne!(private_context.placement.lexical_scope, public_scope);
            checked_workbenches.push((private_context, checked_workbench));
        }
        let context = checked_workbenches[0].0.clone();
        let sibling_context = checked_workbenches[1].0.clone();
        for (index, cell) in [
            (
                0,
                "data InspectionPrivateType = InspectionPrivateType".to_owned(),
            ),
            (0, "checkedLookupValue <- pure (42 :: Int)".to_owned()),
            (1, "privateSiblingValue <- pure (43 :: Int)".to_owned()),
        ] {
            let (binding_context, checked_workbench) = &checked_workbenches[index];
            checked_workbench
                .execute_cell_for_test((*binding_context).clone(), &cell)
                .await
                .expect("checked binding settles");
            checked_workbench
                .access
                .with_machine((*binding_context).clone(), |session, context, _| {
                    let view = session
                        .compile_view_in(context.placement.lexical_scope)
                        .expect("private checked scope remains live");
                    session.capture_inspection_inputs(&view).map_err(|error| {
                        ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                    })?;
                    Ok(())
                })
                .await
                .expect("checked interfaces retained immediately after each installation");
        }
        let inspection_source = source.clone();
        let (view, inputs, prepared) = workbench
            .access
            .with_machine(context.clone(), move |session, context, _| {
                let view = actor_compile_view(session, context, &inspection_source)?;
                let inputs = session
                    .capture_inspection_inputs(view.session_view())
                    .map_err(|error| {
                        ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                    })?;
                let prepared = inspection_source.prepare(&view);
                Ok((view, inputs, prepared))
            })
            .await
            .expect("native input snapshot captures with view");
        assert!(!inputs.view().reachable_values().is_empty());
        let sibling_module = workbench
            .access
            .with_machine(sibling_context.clone(), |session, context, _| {
                let view = session
                    .compile_view_in(context.placement.lexical_scope)
                    .ok_or_else(|| {
                        ResidentActorWorkbenchError::Resident(ResidentError::Session(
                            tidepool_runtime::session::SessionError::DeadScope(
                                context.placement.lexical_scope,
                            ),
                        ))
                    })?;
                Ok(view
                    .reachable_values()
                    .first()
                    .expect("checked sibling owner")
                    .module_name())
            })
            .await
            .expect("sibling owner view");
        assert!(!inputs
            .view()
            .reachable_values()
            .iter()
            .any(|owner| owner.module_name() == sibling_module));
        for _ in 0..2 {
            let inspected = tidepool_testing::with_settlement(|settlement| {
                inspect_lookup_queries(
                    &view,
                    Some(&inputs),
                    &prepared.preamble,
                    &prepared.imports,
                    &prepared.include,
                    &prepared.injected,
                    &context.haskell_effects_alias,
                    &[InspectionQuery::Info("checkedLookupValue".into())],
                    None,
                    settlement,
                )
            })
            .expect("native bound lookup succeeds");
            assert!(
                matches!(&inspected[..], [tidepool_runtime::session::InspectionResult::Info { entries, .. }]
                if entries.iter().any(|entry| entry.name == "checkedLookupValue"))
            );
        }
        let query = tidepool_runtime::session::NameQuery {
            scope: tidepool_runtime::session::NameScope::Current,
            namespace: tidepool_runtime::session::NameNamespace::Value,
            name: "checkedLookupValue".into(),
        };
        let provenance = structured_provenance(&view, &source, query.scope.clone());
        let mut queries = vec![
            InspectionQuery::TypeOf("checkedLookupValue".into()),
            InspectionQuery::StructuredInfo {
                query: query.clone(),
                provenance: provenance.clone(),
            },
            InspectionQuery::StructuredType {
                query,
                provenance: provenance.clone(),
            },
            InspectionQuery::StructuredInfo {
                query: tidepool_runtime::session::NameQuery {
                    scope: tidepool_runtime::session::NameScope::Current,
                    namespace: tidepool_runtime::session::NameNamespace::Value,
                    name: "privateSiblingValue".into(),
                },
                provenance: provenance.clone(),
            },
        ];
        let private_modules = [
            inputs.view().reachable_values()[0].module_name(),
            sibling_module,
            view.library()
                .expect("checked declaration owner")
                .module_name(),
        ];
        for (index, module) in private_modules.iter().enumerate() {
            let scope = tidepool_runtime::session::NameScope::PublicModule(module.clone());
            queries.push(InspectionQuery::StructuredInfo {
                query: tidepool_runtime::session::NameQuery {
                    scope: scope.clone(),
                    namespace: if index == 2 {
                        tidepool_runtime::session::NameNamespace::Type
                    } else {
                        tidepool_runtime::session::NameNamespace::Value
                    },
                    name: if index == 2 {
                        "InspectionPrivateType"
                    } else {
                        "checkedLookupValue"
                    }
                    .into(),
                },
                provenance: structured_provenance(&view, &source, scope),
            });
        }
        let scope = tidepool_runtime::session::NameScope::PublicModule("Data.Maybe".into());
        queries.push(InspectionQuery::StructuredInfo {
            query: tidepool_runtime::session::NameQuery {
                scope: scope.clone(),
                namespace: tidepool_runtime::session::NameNamespace::Value,
                name: "isJust".into(),
            },
            provenance: structured_provenance(&view, &source, scope),
        });
        let inspection_source = source.clone();
        let (batch, status) = workbench
            .access
            .with_machine(context.clone(), move |session, context, _| {
                let batch = tidepool_testing::with_settlement(|settlement| {
                    inspect_actor_batch(session, context, &inspection_source, &queries, settlement)
                })?;
                let status = tidepool_testing::with_settlement(|settlement| {
                    run_status_discovery(
                        session,
                        context,
                        &inspection_source,
                        crate::status_tool::StatusDiscovery::Bindings,
                        settlement,
                    )
                })?;
                Ok((batch, status))
            })
            .await
            .expect("modern inspection consumers accept checked native input");
        assert_eq!(batch.len(), 8);
        assert!(
            matches!(&batch[0], Ok(tidepool_runtime::session::InspectionResult::Type { display, .. })
            if display.contains("Int"))
        );
        assert!(
            matches!(&batch[1], Ok(tidepool_runtime::session::InspectionResult::StructuredInfo(Ok(info)))
            if info.identifier.name == "checkedLookupValue" && info.provenance == provenance)
        );
        assert!(
            matches!(&batch[2], Ok(tidepool_runtime::session::InspectionResult::StructuredType(Ok(info)))
            if info.identifier.name == "checkedLookupValue" && info.expression.canonical == "Int"
                && info.provenance == provenance)
        );
        assert!(
            matches!(&batch[3], Ok(tidepool_runtime::session::InspectionResult::StructuredInfo(
            Err(tidepool_runtime::session::QueryError::Unknown(query))))
            if query.name == "privateSiblingValue")
        );
        for (result, module) in batch[4..7].iter().zip(&private_modules) {
            assert!(
                matches!(result, Ok(tidepool_runtime::session::InspectionResult::StructuredInfo(
                Err(tidepool_runtime::session::QueryError::UnknownModule(rejected)))) if rejected == module)
            );
        }
        assert!(
            matches!(&batch[7], Ok(tidepool_runtime::session::InspectionResult::StructuredInfo(Ok(info)))
            if info.identifier.name == "isJust")
        );
        let status = status.expect("status binding types are available");
        assert!(status.contains("checkedLookupValue :: Int"), "{status}");
        assert!(!status.contains("<type unavailable>"), "{status}");
    }

    #[tokio::test]
    async fn lookup_revalidation_is_actor_scoped_and_checkout_is_free_during_rpc() {
        with_test_compiler_owner(
            lookup_revalidation_is_actor_scoped_and_checkout_is_free_during_rpc_with_compiler_owner(
            ),
        )
        .await;
    }

    async fn lookup_revalidation_is_actor_scoped_and_checkout_is_free_during_rpc_with_compiler_owner(
    ) {
        for sibling_write in [false, true] {
            let (machines, context, source, _root) = actor_lookup_registry_fixture();
            let workbench =
                ResidentActorWorkbench::new(Arc::clone(&machines), source.clone(), None);
            let (workbench, context) = workbench
                .admit_private_cell_for_test(context)
                .await
                .unwrap();
            let workbench = Arc::new(workbench);
            let validation = if sibling_write {
                concat!(
                    "lookupValidation <- LookupApi.lookupRaw (LookupApi.lookupRequest [\"pollResponse\"]) >>= \\result -> ",
                    "if lookupIssue result == Nothing && not (null (lookupResults result)) ",
                    "then pure True else error \"unrelated sibling write invalidated lookup\""
                )
            } else {
                concat!(
                    "lookupValidation <- LookupApi.lookupRaw (LookupApi.lookupRequest [\"pollResponse\"]) >>= \\result -> ",
                    "if lookupIssue result == Just \"lookup compile view changed\" && null (lookupResults result) ",
                    "then pure True else error \"stale lookup metadata escaped\""
                )
            };
            let step = workbench
                .begin_cell_for_test(
                    context.clone(),
                    ParsedBlock {
                        ordinal: 1,
                        total: 1,
                        source: validation.into(),
                    },
                )
                .await
                .expect("lookup fragment compiles and suspends");
            let (fragment, outcome) = match step {
                ResidentWorkbenchStep::Running { fragment, outcome } => (fragment, outcome),
                ResidentWorkbenchStep::Rejected(rejection) => {
                    panic!("lookup fixture rejected: {rejection:#?}")
                }
                ResidentWorkbenchStep::Committed { output, .. } => {
                    panic!("lookup fixture completed before the effect: {output}")
                }
                _ => panic!("lookup fixture returned an unexpected workbench step"),
            };
            let ResidentWorkbenchSuspension::Ask { hole, .. } = *outcome else {
                panic!("lookup effect should park a continuation")
            };
            let (probe, completed, release) = lookup_inspection_probe::install();
            let trace_path = lookup_trace_path();
            let requests_before = compiler_trace_started_ids(&trace_path);
            let task_workbench = Arc::clone(&workbench);
            let task_context = context.clone();
            let task = tokio::spawn(CompilerCloseOwner::current().unwrap().scope(async move {
                task_workbench
                    .resume_lookup(
                        task_context,
                        hole,
                        real_lookup_request(varied_lookup_queries()),
                        crate::UsagePointerTable::default(),
                        None,
                    )
                    .await
            }));

            let trace_for_wait = trace_path.clone();
            let active_request = tokio::task::spawn_blocking(move || {
                wait_for_new_compiler_request(&trace_for_wait, &requests_before)
            })
            .await
            .expect("request-start waiter joins");
            assert!(!active_request.is_empty());
            tokio::time::timeout(
                Duration::from_secs(30),
                workbench
                    .access
                    .with_machine(context.clone(), |_, _, _| Ok(())),
            )
            .await
            .expect("machine checkout is released while GHC inspection is active")
            .expect("machine checkout succeeds during GHC inspection");
            assert!(
                !compiler_request_event(&trace_path, &active_request, "compiler request finished"),
                "exact GHC request {active_request} finished before the competing checkout"
            );

            let gate_waiter = tokio::task::spawn_blocking(move || {
                completed
                    .recv_timeout(Duration::from_secs(90))
                    .expect("real inspection result reached the revalidation gate")
            });
            gate_waiter.await.expect("inspection gate waiter joins");
            assert!(compiler_request_event(
                &trace_path,
                &active_request,
                "compiler request finished"
            ));

            if sibling_write {
                let sibling_parent_context = context.clone();
                let sibling_source = source.clone();
                workbench
                    .access
                    .with_machine(context.clone(), move |session, _, _| {
                        let sibling = session.mint_isolated_scope();
                        let mut sibling_context = sibling_parent_context;
                        sibling_context.placement.lexical_scope = sibling;
                        let (binder, compiled, generation) = compile_host_binding(
                            session,
                            &sibling_context,
                            &sibling_source,
                            "lookup_sibling_value",
                            TEXT_BINDING_TYPE_NAME,
                            TEXT_BINDING_ANCHOR,
                            text_binding_carrier_imports(),
                            true,
                        )?;
                        tidepool_testing::with_settlement(|settlement| {
                            session.mount_text_binding_in(
                                sibling,
                                &binder,
                                generation,
                                compiled.into_code(),
                                "unrelated sibling value",
                                settlement,
                            )
                        })
                        .map_err(ResidentActorWorkbenchError::Resident)?;
                        Ok(())
                    })
                    .await
                    .expect("a sibling-only binding commits");
            } else {
                workbench
                    .access
                    .with_machine(context.clone(), move |session, context, _| {
                        tidepool_testing::with_settlement(|settlement| {
                            session.define_scoped_in(
                                context.placement.lexical_scope,
                                &["data LookupViewChanged = LookupViewChanged"],
                                settlement,
                            )
                        })
                        .map_err(|error| {
                            ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                        })?;
                        Ok(())
                    })
                    .await
                    .expect("visible declaration changes the actor compile view");
            }

            drop(probe);
            release.send(()).expect("release real lookup result");
            let outcome = task
                .await
                .expect("lookup task joins")
                .expect("lookup resumes after revalidation");
            let settled = workbench
                .settle_item(context.clone(), *fragment, outcome)
                .await
                .expect("lookup continuation settles");
            assert!(
                matches!(settled, ResidentWorkbenchStep::Committed { .. }),
                "Haskell continuation validates the stale or preserved lookup result"
            );
        }
    }

