    async fn planned_cell_defers_declaration_until_its_admitted_item_with_compiler_owner() {
        let (machines, context, source, _root) = actor_registry_fixture();
        let workbench = ResidentActorWorkbench::new(machines, source, None);
        let public_context = context.clone();
        let (workbench, context) = workbench
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
        let cell = "plannedDecl args = length (args :: [Int])".to_owned();
        let (checked, prepared) = workbench
            .prepare_cell(context.clone(), cell.clone())
            .await
            .expect("admitted declaration program");
        assert_eq!(checked.items.len(), 1);
        workbench
            .access
            .with_machine(context.clone(), |session, context, _| {
                assert!(!session
                    .current_decl_heads_in(context.placement.lexical_scope)
                    .iter()
                    .any(|(name, _)| name == "plannedDecl"));
                Ok(())
            })
            .await
            .unwrap();
        let PreparedCell { mut items, .. } = prepared;
        assert!(matches!(&items[0].ready, PreparedCellStep { item, .. }
            if item.kind() == tidepool_toolchain::checked_cell::CheckedItemKind::Declaration));
        let step = workbench
            .begin_prepared_cell_item(
                context.clone(),
                ParsedBlock {
                    ordinal: 1,
                    total: 1,
                    source: cell,
                },
                items.remove(0),
            )
            .await
            .expect("admitted declaration settles");
        assert!(matches!(step, ResidentWorkbenchStep::Committed { .. }));
        workbench
            .access
            .with_machine(context.clone(), |session, context, _| {
                assert!(session
                    .current_decl_heads_in(context.placement.lexical_scope)
                    .iter()
                    .any(|(name, _)| name == "plannedDecl"));
                Ok(())
            })
            .await
            .unwrap();
        workbench
            .access
            .with_machine(public_context.clone(), |session, context, _| {
                assert!(
                    !session
                        .current_decl_heads_in(context.placement.lexical_scope)
                        .iter()
                        .any(|(name, _)| name == "plannedDecl"),
                    "native declaration execution remains private before publication"
                );
                Ok(())
            })
            .await
            .unwrap();
        let published = workbench_runner_for_test(&workbench)
            .publish_private_execution(
                context,
                workbench.private_execution.as_ref().unwrap().clone(),
            )
            .await
            .unwrap();
        assert!(matches!(
            published,
            PrivateExecutionPublication::Manifest { .. }
        ));
        workbench
            .access
            .with_machine(public_context, |session, context, _| {
                assert!(session
                    .current_decl_heads_in(context.placement.lexical_scope)
                    .iter()
                    .any(|(name, _)| name == "plannedDecl"));
                Ok(())
            })
            .await
            .unwrap();
    }

    /// The native program retains its mounted request input across preparation;
    /// later items and closures retain the exact original input after a new mount.
    #[tokio::test]
    async fn planned_cell_keeps_request_json_input_owned_across_native_preparation() {
        with_test_compiler_owner(planned_cell_keeps_request_json_input_owned_across_native_preparation_with_compiler_owner()).await;
    }

    async fn planned_cell_keeps_request_json_input_owned_across_native_preparation_with_compiler_owner(
    ) {
        let (machines, public, source, _root) = actor_registry_fixture();
        let workbench = ResidentActorWorkbench::new(machines, source, None)
            .with_json_input(Some(serde_json::json!({"greeting": "hi"})));
        let (workbench, context) = workbench
            .admit_private_cell_for_test(public.clone())
            .await
            .unwrap();
        let (carrier, host_dependencies) = workbench
            .prepare_host_input(context.clone(), HostCarrierKind::Json, None)
            .await
            .expect("host JSON has its original checked interface");
        assert_eq!(
            carrier.binding().unwrap().host_authority,
            Some(tidepool_runtime::session::turn::HostBindingAuthority::JsonValue)
        );
        let carrier = workbench
            .refuse_host_payload_for_test(context.clone(), carrier)
            .await;
        let host_owner = workbench
            .mount_prepared_json_input(
                context.clone(),
                carrier,
                serde_json::json!({"greeting": "hi"}),
            )
            .await
            .unwrap();
        drop(host_dependencies);
        workbench
            .access
            .with_machine(context.clone(), |session, context, _| {
                let view = session
                    .compile_view_in(context.placement.lexical_scope)
                    .unwrap();
                let input = session.capture_inspection_inputs(&view).unwrap();
                assert_eq!(input.view().reachable_values().len(), 1);
                let owner = input.view().reachable_values()[0];
                assert!(!view.session_root().join(owner.relative_hs_path()).exists());
                Ok(())
            })
            .await
            .unwrap();
        let cell = "seen <- pure input\nechoed <- pure seen\ncapturedInput <- pure (\\() -> input)"
            .to_string();

        let (checked, prepared) = workbench
            .prepare_checked_cell(
                context.clone(),
                cell,
                workbench.compilation_authority.clone().unwrap(),
                workbench.private_execution.clone().unwrap(),
                Some(host_owner),
            )
            .await
            .expect("a three-item native program retains its request input and closure");
        assert_eq!(
            checked.items.len(),
            3,
            "all three bind statements must classify as items: {checked:?}"
        );
        assert!(
            checked
                .items
                .iter()
                .all(|item| item.verdict.kind == TurnKind::Bind),
            "every item is a binding: {checked:?}"
        );
        let PreparedCell {
            items,
            dependencies,
        } = prepared;
        assert_eq!(items.len(), 3);
        assert!(
            items.iter().all(|item| item.ready.item.kind()
                == tidepool_toolchain::checked_cell::CheckedItemKind::Bind),
            "all three items retain their admitted program authority"
        );
        let input_name = dependencies
            ._input
            .as_ref()
            .unwrap()
            .mounted_input()
            .binder
            .name
            .clone();
        for (index, (observed, item)) in checked.items.iter().zip(items).enumerate() {
            let step = workbench
                .begin_prepared_cell_item(
                    context.clone(),
                    ParsedBlock {
                        ordinal: index + 1,
                        total: checked.items.len(),
                        source: observed.source.clone(),
                    },
                    item,
                )
                .await
                .expect("admitted JSON item executes");
            match step {
                ResidentWorkbenchStep::Running { fragment, outcome } => {
                    workbench
                        .settle_item(context.clone(), *fragment, (*outcome).into())
                        .await
                        .expect("JSON bind settles");
                }
                ResidentWorkbenchStep::Committed { .. } => {}
                _ => panic!("JSON item did not commit"),
            }
        }
        drop(dependencies);
        tokio::time::timeout(Duration::from_secs(10), async {
            loop {
                let retired = workbench
                    .access
                    .with_machine(context.clone(), {
                        let input_name = input_name.clone();
                        move |session, context, _| {
                            let scope = context.placement.lexical_scope;
                            assert!(session.current_binding_in(scope, "seen").is_some());
                            assert!(session.current_binding_in(scope, "echoed").is_some());
                            assert!(session.current_binding_in(scope, "capturedInput").is_some());
                            Ok(session.current_binding_in(scope, &input_name).is_none())
                        }
                    })
                    .await
                    .unwrap();
                if retired {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the input owner retires while completed JSON values remain bound");
        let workbench = workbench.with_json_input(None);
        let original = workbench
            .host_binding_identity_for_test(context.clone(), "seen")
            .await;
        let original_echo = workbench
            .host_binding_identity_for_test(context.clone(), "echoed")
            .await;
        let original_capture = workbench
            .host_binding_identity_for_test(context.clone(), "capturedInput")
            .await;
        workbench
            .execute_cell_for_test(
                context.clone(),
                &tidepool_testing::fixture_source("exomonad/actor/src/fixtures/host-json-first.hs"),
            )
            .await
            .unwrap();
        workbench
            .publish_completed_cell_for_test(context)
            .await
            .unwrap();
        let (workbench, context) = workbench
            .admit_private_cell_for_test(public.clone())
            .await
            .unwrap();
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "seen")
                .await,
            original
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "echoed")
                .await,
            original_echo
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "capturedInput")
                .await,
            original_capture
        );
        workbench
            .execute_cell_for_test(context.clone(), "data Value = SourceValue Bool")
            .await
            .unwrap();
        let (carrier, host_dependencies) = workbench
            .prepare_host_input(context.clone(), HostCarrierKind::Json, None)
            .await
            .expect("second JSON mount authenticates retained Value and Scientific owners");
        let binder = carrier.binding().unwrap();
        assert_eq!(
            binder.host_authority,
            Some(tidepool_runtime::session::turn::HostBindingAuthority::JsonValue)
        );
        let second_input_name = binder.name.clone();
        let carrier = workbench
            .refuse_host_payload_for_test(context.clone(), carrier)
            .await;
        let input = workbench
            .mount_prepared_json_input(
                context.clone(),
                carrier,
                serde_json::json!({"greeting": "again", "count": 42}),
            )
            .await
            .unwrap();
        drop(host_dependencies);
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "capturedInput")
                .await,
            original_capture
        );
        let source =
            tidepool_testing::fixture_source("exomonad/actor/src/fixtures/host-json-retained.hs");
        let (checked, prepared) = workbench
            .prepare_checked_cell(
                context.clone(),
                source,
                workbench.compilation_authority.clone().unwrap(),
                workbench.private_execution.clone().unwrap(),
                Some(input),
            )
            .await
            .expect("second native program uses its new input and the original JSON values");
        let PreparedCell {
            items,
            dependencies,
        } = prepared;
        assert_eq!(items.len(), 2);
        for (index, (observed, item)) in checked.items.iter().zip(items).enumerate() {
            let step = workbench
                .begin_prepared_cell_item(
                    context.clone(),
                    ParsedBlock {
                        ordinal: index + 1,
                        total: checked.items.len(),
                        source: observed.source.clone(),
                    },
                    item,
                )
                .await
                .unwrap();
            let settled = match step {
                ResidentWorkbenchStep::Running { fragment, outcome } => workbench
                    .settle_item(context.clone(), *fragment, (*outcome).into())
                    .await
                    .unwrap(),
                other => other,
            };
            assert!(matches!(settled, ResidentWorkbenchStep::Committed { .. }));
        }
        drop(dependencies);
        workbench
            .wait_for_host_input_retirement_for_test(context.clone(), second_input_name)
            .await;
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "seen")
                .await,
            original
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "echoed")
                .await,
            original_echo
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(context.clone(), "capturedInput")
                .await,
            original_capture
        );
        workbench
            .host_binding_identity_for_test(context.clone(), "secondSeen")
            .await;
        workbench
            .publish_completed_cell_for_test(context)
            .await
            .unwrap();
        assert_eq!(
            workbench
                .host_binding_identity_for_test(public.clone(), "seen")
                .await,
            original
        );
        assert_eq!(
            workbench
                .host_binding_identity_for_test(public, "capturedInput")
                .await,
            original_capture
        );
    }

    #[tokio::test]
    async fn scope_live_closure_survives_body_realm_retirement() {
        with_test_compiler_owner(
            scope_live_closure_survives_body_realm_retirement_with_compiler_owner(),
        )
        .await;
    }

    async fn scope_live_closure_survives_body_realm_retirement_with_compiler_owner() {
        let (session, context, mut source, _root) = host_mount_fixture_with_effects(
            |_| {},
            &[tidepool_mcp::resource_scopes_decl()],
            "'[ResourceScopes]",
        );
        source
            .workbench_imports
            .extend_text("qualified Tidepool.Scope as Scope");
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(context.placement.session, Box::new(session));
        let workbench = ResidentActorWorkbench::new(machines, source, None);
        let (workbench, context) = workbench
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
        let runner = workbench_runner_for_test(&workbench);
        let code = include_str!("fixtures/scope-live-result.hs");
        let (checked, prepared) = workbench
            .prepare_cell(context.clone(), code.into())
            .await
            .unwrap();
        assert_eq!(checked.items.len(), 1);
        let PreparedCell {
            mut items,
            dependencies: _dependencies,
        } = prepared;
        let step = workbench
            .begin_prepared_cell_item(
                context.clone(),
                ParsedBlock {
                    ordinal: 1,
                    total: 1,
                    source: code.into(),
                },
                items.remove(0),
            )
            .await
            .unwrap();
        let ResidentWorkbenchStep::Running { fragment, outcome } = step else {
            panic!("scope body suspends")
        };
        let outcome: ResidentOutcome = (*outcome).into();
        let ResidentOutcome::Suspended { hole, request, .. } = &outcome else {
            panic!("scope delimiter suspends")
        };
        let hole = hole.clone();
        let request = request.clone();
        let parent_realm = context.placement.resource_scope;
        workbench
            .access
            .with_machine(context.clone(), move |session, _, _| {
                let ResidentRequest::ResourceScopes(
                    crate::generated::resource_scopes::ResourceScopesReq::ScopeRunWith(site, _),
                ) = ResidentRequest::decode(&request, session.data_con_table())?
                else {
                    panic!("scope callback follows the generated request schema")
                };
                let custody = session.outstanding_custody();
                for (invalid_site, realm) in [
                    (-1, parent_realm),
                    (i64::MAX, parent_realm),
                    (site, RealmId::fresh()),
                ] {
                    assert!(matches!(
                        capture_scope_boundary(session, hole.clone(), invalid_site, realm),
                        Err(ResidentActorWorkbenchError::ActorProtocol(_))
                    ));
                    assert_eq!(session.outstanding_custody(), custody);
                }
                Ok(())
            })
            .await
            .unwrap();
        let boundary = runner
            .capture_boundary(context.clone(), outcome, context.placement.resource_scope)
            .await
            .unwrap();
        let ResidentActorBoundary::ScopeRun {
            continuation,
            callback,
        } = boundary
        else {
            panic!("scope delimiter captures live callback")
        };
        let body_realm = RealmId::fresh();
        let body = runner
            .run_rooted_entry(context.clone(), callback, body_realm)
            .await
            .unwrap();
        let boundary = runner
            .capture_boundary(context.clone(), body, body_realm)
            .await
            .unwrap();
        assert!(matches!(
            boundary,
            ResidentActorBoundary::ScopeDone { token: 0, .. }
        ));
        runner
            .close_realm(context.clone(), body_realm)
            .await
            .unwrap();
        assert!(
            runner
                .resume_value(context.clone(), continuation.clone(), ())
                .await
                .is_err(),
            "scope status site rejects a reply with another shape before consuming its continuation"
        );
        let resumed = runner
            .resume_value(
                context.clone(),
                continuation,
                (
                    Ok::<(), tidepool_bridge_effects::ScopeFailure>(()),
                    Ok::<(), tidepool_bridge_effects::CleanupError>(()),
                ),
            )
            .await
            .unwrap();
        let settled = workbench
            .settle_item(context, *fragment, resumed)
            .await
            .unwrap();
        let ResidentWorkbenchStep::Committed { .. } = settled else {
            panic!("parent applies the returned live closure and commits after scope retirement")
        };
    }

