    async fn current_request_cell_compiles_closed_site_evidence_with_compiler_owner() {
        let (machines, mut context, mut source, _root) = actor_registry_fixture();
        context.haskell_effects_alias = "'[Exomonad.Replies]".into();
        source
            .workbench_imports
            .extend_text("qualified Tidepool.Agent.Reply as TidepoolReply");
        let workbench = ResidentActorWorkbench::new(machines, source, None);
        let (workbench, context) = workbench
            .admit_private_cell_for_test(context)
            .await
            .unwrap();
        let cell = "scope <- (TidepoolReply.currentRequest :: Eff '[Exomonad.Replies] (TidepoolReply.RequestScope () ()))".to_owned();
        let (checked, prepared) = workbench
            .prepare_cell(context.clone(), cell.clone())
            .await
            .expect("closed request scope compiles with site evidence");
        assert_eq!(checked.items.len(), 1);
        let PreparedCell { mut items, .. } = prepared;
        let PreparedCellStep { prefix, item } = items.remove(0).ready;
        let reservation = workbench
            .access
            .with_machine(context, move |session, _, _| {
                session.admit_checked_item(prefix, item).map_err(|error| {
                    ResidentActorWorkbenchError::Resident(ResidentError::Session(error))
                })
            })
            .await
            .unwrap();
        let compiled = consume_admitted_cell_item(
            reservation,
            &ParsedBlock {
                ordinal: 1,
                total: 1,
                source: cell,
            },
        )
        .unwrap();
        let CompiledBlock::Ready(ready) = compiled else {
            panic!("ready request native product")
        };
        let compiled = &ready.compiled;
        assert!(
            compiled.sites().iter().any(|site| site.inputs.len() == 3),
            "currentRequest carries input, result, and ResponseResult result evidence"
        );
    }

    /// Publish an alias of the original binding through its checked whole cell,
    /// retaining the value interface's issued package and type evidence.
    async fn publish_request_scope_test_input(
        workbench: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        context: crate::ActorSessionContext,
    ) -> Result<tidepool_repr::SessionVarId, ResidentActorWorkbenchError> {
        let scope = context.placement.lexical_scope;
        workbench
            .publish_cell_for_test(context.clone(), "sessionInput <- pure sourceValue")
            .await?;

        workbench
            .access
            .with_machine(context, move |session, _, _| {
                session
                    .current_binding_in(scope, "sessionInput")
                    .map(|binding| binding.0)
                    .ok_or_else(|| {
                        ResidentActorWorkbenchError::InputMount(
                            "sessionInput alias was not published in the request scope".into(),
                        )
                    })
            })
            .await
    }

    /// Compile one authentic producer and receiver, then retain two original
    /// native inputs for independent activation mounts in the same machine.
    fn activation_input_fixture(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
    ) -> (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        Vec<tidepool_runtime::session::RuntimeActivationInput>,
        tempfile::TempDir,
    ) {
        let (mut session, context, source, parked, root) = activation_session_fixture(configure);
        let inputs = parked
            .into_iter()
            .map(|(hole, input)| {
                let activation_id = hole.cont_id().to_owned();
                assert!(matches!(
                    session.abort(&activation_id, "fixture retained original input".into()),
                    Err(ResidentError::Run(tidepool_runtime::RuntimeError::Jit(
                        tidepool_effect::EffectError::Handler(reason)
                    ))) if reason == "ask aborted by caller: fixture retained original input"
                ));
                assert!(!session.parked_holes().contains(&activation_id.as_str()));
                input
            })
            .collect();
        (session, context, source, inputs, root)
    }

    type ActivationSessionFixture = (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        Vec<(
            ResidentHole,
            tidepool_runtime::session::RuntimeActivationInput,
        )>,
        tempfile::TempDir,
    );

    pub(crate) fn activation_session_fixture(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
    ) -> ActivationSessionFixture {
        activation_session_fixture_counted(configure, false)
    }

    fn activation_session_fixture_counted(
        configure: impl FnOnce(&mut tidepool_runtime::session::SessionLib),
        renderer_values: bool,
    ) -> ActivationSessionFixture {
        use tidepool_runtime::session::{ModuleEnv, SessionLib};
        let (_, mut context, _, _) = host_mount_fixture();
        let declarations = [
            tidepool_mcp::agent_tools_decl(),
            tidepool_mcp::agent_session_decl(),
            tidepool_mcp::actor_decl(),
            tidepool_mcp::actor_kernel_decl(),
            tidepool_mcp::actor_local_decl(),
            tidepool_mcp::fs_read_decl(),
            tidepool_mcp::worktree_decl(),
            tidepool_mcp::notifications_decl(),
            tidepool_mcp::console_decl(),
            tidepool_mcp::sleep_decl(),
        ];
        let effects = tidepool_mcp::ensure_effects_module(&declarations).unwrap();
        let include = fixture_include_roots(&effects);
        let mut preamble = tidepool_mcp::build_notebook_preamble(&declarations, false);
        for import in [
            "Tidepool.Agent.Reply (Replies)",
            "Tidepool.Agent.Watch (Watches)",
            "Tidepool.Agent.Ref.Internal (AgentProtocol(..))",
            "qualified Tidepool.Agent.Ref.Internal as Ref",
            "qualified Tidepool.Actors.Internal.Agent as Agents",
            "qualified Tidepool.Effects.Core as Core",
        ] {
            preamble = insert_preamble_imports(&preamble, import);
        }
        context.haskell_effects_alias = "'[Replies]".into();
        context.effect_policy = tidepool_effect::EffectRunPolicy::SuspendAll;
        context.placement.lexical_scope = ScopeId::ROOT;
        let root = tempfile::tempdir().unwrap();
        let mut lib = SessionLib::open(
            context.placement.session,
            root.path(),
            ModuleEnv::standalone_default(),
        )
        .unwrap()
        .with_validation_include(include.clone());
        configure(&mut lib);
        let mut session = ResidentSession::unbootstrapped(
            frunk::HNil,
            tidepool_mcp::CapturedOutput::new(),
            tidepool_runtime::DEFAULT_NURSERY_SIZE,
            Some(lib),
        );
        session
            .set_actor_execution(
                context.run_context(),
                context.effect_policy,
                context.live_payload,
            )
            .unwrap();
        let source = ActorWorkbenchSource::new(preamble, include);
        let view = actor_compile_view(&session, &context, &source).unwrap();
        let prepared = source.prepare(&view);
        let templates = resident_workbench_templates(
            &prepared.preamble,
            context.haskell_effects_alias.expression(),
            &prepared.imports,
        );
        let include = prepared
            .include
            .iter()
            .map(PathBuf::as_path)
            .collect::<Vec<_>>();
        let producer_text = if renderer_values {
            tidepool_testing::fixture_source(
                "tidepool/runtime/src/session/fixtures/activation-input-twenty-renderers.hs",
            )
        } else {
            tidepool_testing::fixture_source(
                "tidepool/runtime/src/session/fixtures/activation-input-function.hs",
            )
        };
        let TurnResult::Bind {
            compiled: producer,
            bound: producer_bound,
            ..
        } = tidepool_testing::with_settlement(|settlement| {
            tidepool_runtime::session::turn::run_turn(
                TurnRequest {
                    exact_context: None,
                    session_id: None,
                    turn_text: &producer_text,
                    templates: &templates,
                    include: &include,
                    session_root: view.session_root(),
                    inject_modules: &[],
                    gen: view.next_value_generation().0,
                    verdict: None,
                    target: None,
                    retained_imports: &[],
                },
                settlement,
            )
        })
        .unwrap()
        else {
            panic!("native input producer must execute a bind");
        };
        assert!(
            producer_bound.is_empty(),
            "request producer creates no persistent binding"
        );
        let previous_context = session.run_context();
        let execution = Arc::new(
            session
                .begin_ephemeral_private_execution(context.placement.lexical_scope)
                .unwrap(),
        );
        let mut private_context = context.clone();
        private_context.placement.lexical_scope = execution.private_scope();
        session
            .set_run_context(private_context.run_context())
            .unwrap();
        let (receiver_source, snapshot) = snapshot_cell_program(
            &mut session,
            &private_context,
            source.clone(),
            None,
            None,
            CellSnapshotAdmission::PrivateExecution(&execution),
        )
        .unwrap();
        let prepared = receiver_source.prepare(&snapshot.view);
        let preamble =
            cell_module_preamble(&prepared.preamble, &snapshot.candidate_module.module_name())
                .unwrap();
        let template = resident_cell_check_template(
            &preamble,
            private_context.haskell_effects_alias.expression(),
            &prepared.imports,
        );
        let templates = resident_workbench_templates(
            &prepared.preamble,
            private_context.haskell_effects_alias.expression(),
            &prepared.imports,
        );
        let receiver_text = tidepool_testing::fixture_source(
            "tidepool/runtime/src/session/fixtures/activation-input-receiver.hs",
        );
        let specification = Arc::new(tidepool_toolchain::checked_cell::CheckedCellSpecification {
            admission_digest: [0; 32],
            cell_source: receiver_text.clone(),
            template_source: template.clone(),
            turn_templates: templates
                .iter()
                .map(|template| {
                    let kind = match template.kind {
                        tidepool_runtime::session::TemplateSelector::Decl => "decl",
                        tidepool_runtime::session::TemplateSelector::Bind => "bind",
                        tidepool_runtime::session::TemplateSelector::BindDiscard => "binddiscard",
                        tidepool_runtime::session::TemplateSelector::Expr => "expr",
                    };
                    (kind.into(), template.source.clone())
                })
                .collect(),
            injected_modules: prepared.injected.clone(),
            reserved_declaration_modules: Vec::new(),
        });
        let plan = tidepool_testing::with_settlement(|settlement| {
            tidepool_toolchain::artifacts::parse_cell_plan(
                specification.clone(),
                &prepared.include,
                settlement,
            )
        })
        .unwrap();
        let authority =
            crate::resident_actor::WorkbenchCompilationAuthority::for_test(context.clone());
        let admission = session
            .admit_planned_cell_for_execution(
                execution.clone(),
                plan,
                specification.clone(),
                specification.specification_digest(),
                authority.authority_digest(),
                prepared.include.clone(),
                None,
            )
            .unwrap();
        let (checked, program) = tidepool_testing::with_settlement(|settlement| {
            tidepool_runtime::session::turn::compile_cell_program_admitted(
                admission.clone(),
                settlement,
            )
        })
        .unwrap();
        assert_eq!(
            checked.items.len(),
            1,
            "receiver setup is one grouped binding"
        );
        let prefix = session
            .begin_cell_program(admission, program)
            .unwrap()
            .unwrap();
        let reservation = session
            .admit_checked_item(prefix.clone(), checked.checked_item(0).unwrap())
            .unwrap();
        let TurnResult::Bind {
            compiled: receiver,
            bound,
            ..
        } = tidepool_runtime::session::turn::consume_cell_program_item(reservation.clone())
            .unwrap()
        else {
            panic!("native receiver must install retained bindings");
        };
        assert_eq!(bound.len(), 2, "receiver and original native Unit reply");
        let receiver_interface = receiver
            .certification()
            .unwrap()
            .checked_execution()
            .unwrap()
            .value_interface_certificate()
            .unwrap();
        assert_eq!(
            receiver_interface.owner(),
            tidepool_repr::SessionModule::val(reservation.generation())
        );
        let outcome = tidepool_testing::with_settlement(|settlement| {
            session.run_projected_bind_with_sites(
                "activationReceiverFixture",
                receiver.code(),
                &bound,
                reservation.generation(),
                settlement,
            )
        })
        .unwrap();
        assert!(matches!(outcome, ResidentOutcome::BindingsCommitted { .. }));
        let intent = session.freeze_private_execution(&execution).unwrap();
        let tidepool_runtime::session::ExecutionPublication::Bindings(publication) = session
            .restage_ephemeral_execution_publication(intent)
            .unwrap()
        else {
            panic!("receiver setup publishes only native bindings");
        };
        let ticket = publication.stage().unwrap();
        assert_eq!(
            session
                .publish_staged_public_manifest(
                    ticket,
                    &tidepool_runtime::session::PublicationDecision::new(),
                )
                .unwrap(),
            tidepool_runtime::session::PublicManifestCommit::Ephemeral
        );
        session.set_run_context(previous_context).unwrap();
        drop(receiver);
        drop(reservation);
        drop(prefix);
        drop(execution);
        session.retire_scope(private_context.placement.lexical_scope);
        assert!(session
            .compile_view_in(private_context.placement.lexical_scope)
            .is_none());
        let public = session
            .compile_view_in(context.placement.lexical_scope)
            .unwrap();
        let captured = session.capture_inspection_inputs(&public).unwrap();
        assert!(captured
            .view()
            .reachable_values()
            .contains(&receiver_interface.owner()));
        for binder in &bound {
            assert_eq!(
                session
                    .current_binding_in(context.placement.lexical_scope, &binder.name)
                    .unwrap()
                    .0,
                tidepool_repr::SessionVarId::from_extract(binder.var_id)
            );
        }
        drop(captured);
        let suspend = |outcome| match outcome {
            ResidentOutcome::Suspended { hole, .. } => hole,
            other => panic!("native activation fixture must suspend: {other:?}"),
        };
        let mut reservation = suspend(
            tidepool_testing::with_settlement(|settlement| {
                session.run_with_sites("originalActivationRequests", producer.code(), settlement)
            })
            .unwrap(),
        );
        let mut inputs = Vec::new();
        let requests = if renderer_values { 20 } else { 2 };
        for request in 1_i64..=requests {
            let submission = suspend(
                tidepool_testing::with_settlement(|settlement| {
                    session.resume(reservation, Ok::<i64, ()>(request), settlement)
                })
                .unwrap(),
            );
            let payload = session
                .live_payload_handle(submission.cont_id())
                .unwrap()
                .unwrap();
            let receiver = session
                .retain_binding_custody("activationReceiver")
                .unwrap()
                .unwrap();
            let activation = suspend(
                tidepool_testing::with_settlement(|settlement| {
                    session.run_rooted_application(
                        "originalActivationInput",
                        &receiver,
                        &payload,
                        context.placement.resource_scope,
                        None,
                        settlement,
                    )
                })
                .unwrap(),
            );
            let input = producer
                .sites()
                .iter()
                .filter(|site| !site.inputs.is_empty())
                .find_map(|site| {
                    session
                        .capture_activation_input(
                            &activation,
                            context.placement.resource_scope,
                            site.site,
                        )
                        .ok()
                })
                .expect("original authenticated input site");
            inputs.push((activation, input));
            assert!(session.parked_holes().contains(&submission.cont_id()));
            let next = tidepool_testing::with_settlement(|settlement| {
                session.resume(submission, Ok::<(), ()>(()), settlement)
            })
            .unwrap();
            if request < requests {
                reservation = suspend(next);
            } else {
                break;
            }
        }
        (session, context, source, inputs, root)
    }

    /// Authentic retained input for request-settlement component histories.
    /// Compiler/native admission run once; each history owns a fresh native
    /// decision while sharing the immutable admission and checked input proof.
    pub(crate) struct ActivationPublicationPhaseFixture {
        prepared: PreparedActivationInput,
        session: Mutex<Option<Box<ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>>>>,
        context: crate::ActorSessionContext,
        receipt: Option<tidepool_runtime::session::CheckoutReceipt>,
        _machines: Arc<ActorMachineRegistry<frunk::HNil, tidepool_mcp::CapturedOutput>>,
        run_root: tempfile::TempDir,
        _source_root: tempfile::TempDir,
    }

    impl ActivationPublicationPhaseFixture {
        pub(crate) fn actor(&self) -> crate::ActorRef {
            self.context.actor
        }

        pub(crate) fn fresh_resources(
            &self,
        ) -> (
            Arc<ActivationPublicationResources>,
            Arc<tidepool_runtime::session::PublicationDecision>,
        ) {
            let original = &self.prepared.execution;
            let decision = tidepool_runtime::session::PublicationDecision::new();
            let execution = Arc::new(ExecutionPrivateScope {
                owner: original.owner.clone(),
                public_scope: original.public_scope,
                private_scope: original.private_scope,
                admitted_public: original.admitted_public.clone(),
                admission: original.admission.clone(),
                decision: decision.clone(),
            });
            (
                Arc::new(ActivationPublicationResources {
                    execution,
                    input: self.prepared.admission.clone(),
                }),
                decision,
            )
        }

        pub(crate) fn make_pending(&self) {
            use std::os::unix::fs::PermissionsExt;
            let mut held = self.session.lock();
            let session = held.as_mut().unwrap();
            let owner = self.prepared.execution.owner.durable().unwrap();
            let scope = self.context.placement.lexical_scope;
            let writer = session
                .begin_durable_private_execution(owner, scope)
                .unwrap();
            let intent = session.freeze_private_execution(&writer).unwrap();
            let tidepool_runtime::session::ExecutionPublication::Bindings(base) = session
                .restage_execution_publication(owner.clone(), intent)
                .unwrap()
            else {
                panic!("empty native writer has no declaration projection");
            };
            let ticket = base.stage().unwrap();
            std::fs::set_permissions(self.run_root.path(), std::fs::Permissions::from_mode(0o300))
                .unwrap();
            let outcome = session.publish_staged_public_manifest(
                ticket,
                &tidepool_runtime::session::PublicationDecision::new(),
            );
            std::fs::set_permissions(self.run_root.path(), std::fs::Permissions::from_mode(0o700))
                .unwrap();
            assert!(matches!(
                outcome.unwrap(),
                tidepool_runtime::session::PublicManifestCommit::PublishedDurabilityUnconfirmed { .. }
            ));
            assert!(!self.prepared.execution.owner.is_ready());
        }

        pub(crate) fn make_ready(&self) {
            self.session
                .lock()
                .as_mut()
                .unwrap()
                .confirm_durable_public_scope(
                    self.prepared.execution.owner.durable().unwrap(),
                    self.context.placement.lexical_scope,
                )
                .unwrap();
            assert!(self.prepared.execution.owner.is_ready());
        }
    }

    impl Drop for ActivationPublicationPhaseFixture {
        fn drop(&mut self) {
            let session = self.session.get_mut().take().unwrap();
            let holes = session
                .parked_holes()
                .into_iter()
                .map(str::to_owned)
                .collect();
            self._machines
                .settle_suspended(self.receipt.take().unwrap(), session, holes);
        }
    }

