    async fn activation_publication_phase_fixture_with_compiler_owner(
    ) -> ActivationPublicationPhaseFixture {
        struct RunOwner {
            root: PathBuf,
            _lock: std::fs::File,
        }
        impl tidepool_runtime::session::RecoveryRunAuthority for RunOwner {
            fn owns_run(&self, root: &std::path::Path) -> std::io::Result<bool> {
                Ok(root.canonicalize()? == self.root)
            }
        }
        let run_root = tempfile::tempdir().unwrap();
        let lock = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(run_root.path().join("run-owner.lock"))
            .unwrap();
        lock.try_lock().unwrap();
        let authority = Arc::new(RunOwner {
            root: run_root.path().canonicalize().unwrap(),
            _lock: lock,
        });
        let (mut session, mut context, source, mut inputs, source_root) =
            activation_input_fixture(|lib| {
                tidepool_testing::with_settlement(|settlement| {
                    lib.attach_owned_recovery_graph_v3(
                        run_root.path().join("declarations.json"),
                        authority,
                        settlement,
                    )
                })
                .unwrap();
            });
        context.placement.lexical_scope = session.mint_scope(ScopeId::ROOT).unwrap();
        let path = tidepool_repr::ActorPath::parse("root/activation-phases").unwrap();
        let durable =
            tidepool_runtime::session::RecoveryPublicOwner::new(&path, context.actor.incarnation.0)
                .unwrap();
        session
            .initialize_durable_public_scope(durable.clone(), context.placement.lexical_scope)
            .unwrap();
        let descriptor = crate::ActorDescriptor::new("activation phases", context.placement)
            .with_actor_path(path)
            .with_persistence_policy(crate::ActorPersistencePolicy::Durable);
        let owner = crate::resident_actor::WorkbenchPublicOwner::issue(
            &context,
            &descriptor,
            Some(
                session
                    .durable_public_readiness(&durable, context.placement.lexical_scope)
                    .unwrap(),
            ),
        )
        .unwrap();
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(context.placement.session, Box::new(session));
        let runner = ResidentActorRunner::new(machines.clone(), source.clone());
        let execution = Arc::new(
            runner
                .begin_private_execution(
                    context.clone(),
                    owner,
                    tidepool_runtime::session::PublicationDecision::new(),
                )
                .await
                .unwrap(),
        );
        let mut private_context = context.clone();
        private_context.placement.lexical_scope = execution.private_scope;
        let workbench = ResidentActorWorkbench::new(machines.clone(), source, None)
            .with_private_execution(execution);
        let prepared = workbench
            .mount_activation_input(
                private_context,
                inputs.remove(0),
                None,
                "()".into(),
                None,
                Vec::new(),
            )
            .await
            .unwrap();
        drop(inputs);
        drop(workbench);
        drop(runner);
        let (session, receipt) = machines
            .checkout_run(context.placement.session)
            .unwrap()
            .into_parts();
        ActivationPublicationPhaseFixture {
            prepared,
            session: Mutex::new(Some(session)),
            context,
            receipt: Some(receipt),
            _machines: machines,
            run_root,
            _source_root: source_root,
        }
    }

    #[test]
    fn request_annotations_survive_planned_admission() {
        use tidepool_runtime::session::RequestCompileAnnotations;
        use tidepool_toolchain::declaration_join::RequestHelperRecipe;
        let (mut session, context, source, inputs, _root) = activation_input_fixture(|_| {});
        let evidence = inputs[0].type_evidence().clone();
        let signatures = evidence.request_type_signatures().unwrap().clone();
        let execution = Arc::new(
            session
                .begin_ephemeral_private_execution(context.placement.lexical_scope)
                .unwrap(),
        );
        let view = session.compile_view_for_execution(&execution).unwrap();
        let mut private_context = context.clone();
        private_context.placement.lexical_scope = execution.private_scope();
        let prepared = source.prepare(&private_context.compile_view(view.clone()).unwrap());
        let template = resident_cell_check_template(
            &prepared.preamble,
            context.haskell_effects_alias.expression(),
            &prepared.imports,
        );
        let specification = Arc::new(tidepool_toolchain::checked_cell::CheckedCellSpecification {
            admission_digest: [0; 32],
            cell_source: "pure ()".into(),
            template_source: template,
            turn_templates: Vec::new(),
            injected_modules: prepared.injected,
            reserved_declaration_modules: Vec::new(),
        });
        let plan = tidepool_testing::with_settlement(|settlement| {
            tidepool_toolchain::artifacts::parse_cell_plan(
                specification.clone(),
                &prepared.include,
                settlement,
            )
        })
        .unwrap();
        for helper in [RequestHelperRecipe::None, RequestHelperRecipe::ActorReply] {
            let annotations = RequestCompileAnnotations::new(evidence.clone(), helper).unwrap();
            assert!(Arc::ptr_eq(annotations.evidence(), &evidence));
            let admission = session
                .admit_planned_cell_for_execution(
                    execution.clone(),
                    plan.clone(),
                    specification.clone(),
                    specification.specification_digest(),
                    [7; 32],
                    prepared.include.clone(),
                    Some(annotations.into()),
                )
                .unwrap();
            let admitted = admission.view().exact_compile_context().unwrap();
            let annotations = admitted.request_annotations().unwrap();
            assert!(Arc::ptr_eq(annotations.signatures(), &signatures));
            assert_eq!(annotations.helper_recipe(), helper);
        }
        let mut missing = source;
        missing.request_helper_recipe = RequestHelperRecipe::ActorReply;
        assert!(missing.request_annotations().is_err());
    }

