    async fn activation_refuses_reserved_declaration_without_public_mutation_with_compiler_owner() {
        let (session, context, source, mut inputs, _root) = activation_input_fixture(|_| {});
        let public_scope = context.placement.lexical_scope;
        let machines = Arc::new(ActorMachineRegistry::new());
        machines.insert_idle(context.placement.session, Box::new(session));
        let workbench = ResidentActorWorkbench::new(machines, source, None)
            .with_compilation_authority(
                crate::resident_actor::WorkbenchCompilationAuthority::for_test(context.clone()),
            );
        workbench
            .publish_cell_for_test(context.clone(), "sessionInput = ()")
            .await
            .unwrap();
        let before = workbench
            .access
            .with_machine(context.clone(), move |session, _, _| {
                Ok(session.public_visibility_snapshot_in(public_scope).unwrap())
            })
            .await
            .unwrap();
        let descriptor = crate::ActorDescriptor::new("reserved input fixture", context.placement);
        let owner = crate::resident_actor::WorkbenchPublicOwner::issue(&context, &descriptor, None)
            .unwrap();
        let execution = Arc::new(
            workbench_runner_for_test(&workbench)
                .begin_private_execution(
                    context.clone(),
                    owner,
                    tidepool_runtime::session::PublicationDecision::new(),
                )
                .await
                .unwrap(),
        );
        let mut private_context = context.clone();
        private_context.placement.lexical_scope = execution.private_scope;
        let workbench = workbench.with_private_execution(execution);
        let error = workbench
            .mount_activation_input(
                private_context,
                inputs.remove(0),
                None,
                "()".into(),
                None,
                vec![],
            )
            .await
            .unwrap_err();
        assert!(
            matches!(error, ResidentActorWorkbenchError::InputMount(ref detail) if detail.contains("reserved"))
        );
        workbench
            .access
            .with_machine(context, move |session, _, _| {
                assert_eq!(
                    session.public_visibility_snapshot_in(public_scope),
                    Some(before)
                );
                assert!(session
                    .current_decl_heads_in(public_scope)
                    .iter()
                    .any(|(name, _)| name == "sessionInput"));
                assert!(session
                    .current_binding_in(public_scope, "sessionInput")
                    .is_none());
                Ok(())
            })
            .await
            .unwrap();
    }

    async fn renderer_activation_workbench(
        workbench: &ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        context: &crate::ActorSessionContext,
    ) -> (
        ResidentActorWorkbench<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
    ) {
        let descriptor = crate::ActorDescriptor::new("renderer fixture", context.placement);
        let owner =
            crate::resident_actor::WorkbenchPublicOwner::issue(context, &descriptor, None).unwrap();
        let execution = Arc::new(
            workbench_runner_for_test(workbench)
                .begin_private_execution(
                    context.clone(),
                    owner,
                    tidepool_runtime::session::PublicationDecision::new(),
                )
                .await
                .unwrap(),
        );
        let mut private_context = context.clone();
        private_context.placement.lexical_scope = execution.private_scope;
        (
            ResidentActorWorkbench::from_access(workbench.access.sharing(), None)
                .with_private_execution(execution),
            private_context,
        )
    }

    fn distinct_renderer_input_fixture() -> (
        ResidentSession<frunk::HNil, tidepool_mcp::CapturedOutput>,
        crate::ActorSessionContext,
        ActorWorkbenchSource,
        Vec<tidepool_runtime::session::RuntimeActivationInput>,
        tempfile::TempDir,
    ) {
        let (mut session, context, source, parked, root) =
            activation_session_fixture_counted(|_| {}, true);
        let inputs = parked
            .into_iter()
            .map(|(hole, input)| {
                let _ = session.abort(
                    hole.cont_id(),
                    "original parent failed after capture".into(),
                );
                input
            })
            .collect();
        (session, context, source, inputs, root)
    }

    #[tokio::test]
    async fn twenty_distinct_activation_values_share_one_renderer_after_parent_failure() {
        with_test_compiler_owner(async {
            let (session, context, source, inputs, _root) = distinct_renderer_input_fixture();
            assert_eq!(inputs.len(), 20);
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(machines, source, None);
            let submissions = tidepool_extract_cmd::extract_spawn_count();
            let mut bindings = std::collections::BTreeSet::new();
            let mut generations = std::collections::BTreeSet::new();
            let mut scopes = std::collections::BTreeSet::new();
            let producers = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let native_at_selection = Arc::new(std::sync::atomic::AtomicU64::new(0));
            let preparation_start = Arc::new(std::sync::atomic::AtomicU64::new(0));
            let prepared_images = Arc::new(std::sync::atomic::AtomicU64::new(0));
            for (index, input) in inputs.into_iter().enumerate() {
                let (mut activation, private_context) =
                    renderer_activation_workbench(&workbench, &context).await;
                assert!(scopes.insert(private_context.placement.lexical_scope));
                let observed = producers.clone();
                let selected = native_at_selection.clone();
                let started = preparation_start.clone();
                let prepared = prepared_images.clone();
                activation.activation_preview_observer = Some(Arc::new(move |event| {
                    use tidepool_codegen::prepared_program::CompiledProgram;
                    match event {
                        ActivationPublicationObservation::RendererProducer => {
                            observed.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                            started.store(CompiledProgram::successful_image_compilations(), std::sync::atomic::Ordering::SeqCst);
                        }
                        ActivationPublicationObservation::RendererSealed => {
                            prepared.store(CompiledProgram::successful_image_compilations() - started.load(std::sync::atomic::Ordering::SeqCst), std::sync::atomic::Ordering::SeqCst);
                        }
                        ActivationPublicationObservation::RendererSelected(_) => {
                            selected.store(CompiledProgram::successful_image_compilations(), std::sync::atomic::Ordering::SeqCst);
                        }
                        _ => {}
                    }
                    Ok(())
                }));
                let prepared = activation
                    .mount_activation_input(
                        private_context.clone(),
                        input,
                        None,
                        "()".into(),
                        None,
                        Vec::new(),
                    )
                    .await
                    .unwrap();
                assert_eq!(prepared.input_preview.trim(), (index + 1).to_string());
                assert_eq!(tidepool_codegen::prepared_program::CompiledProgram::successful_image_compilations(), native_at_selection.load(std::sync::atomic::Ordering::SeqCst), "fresh preview installation must compile no native images");
                assert!(bindings.insert(prepared.binding.raw()));
                assert!(generations.insert(prepared.admission.generation()));
                // Exactly one fresh interface request each; only the first
                // activation additionally specializes the immutable renderer.
                assert_eq!(
                    tidepool_extract_cmd::extract_spawn_count(),
                    submissions + index as u64 + 2
                );
                drop(prepared);
                drop(activation);
                workbench
                    .access
                    .with_machine(context.clone(), move |session, _, _| {
                        session.retire_scope(private_context.placement.lexical_scope);
                        Ok(())
                    })
                    .await
                    .unwrap();
            }
            assert_eq!(producers.load(std::sync::atomic::Ordering::SeqCst), 1);
            assert!(prepared_images.load(std::sync::atomic::Ordering::SeqCst) > 0, "the shared producer must complete actual native preparation");
            assert_eq!(bindings.len(), 20);
            assert_eq!(generations.len(), 20);
            assert_eq!(scopes.len(), 20);
        })
        .await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn four_concurrent_distinct_values_share_prepared_native_renderer() {
        with_test_compiler_owner(async {
            let (session, context, source, inputs, _root) = distinct_renderer_input_fixture();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(machines, source, None);
            let producers = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let sealed_count = Arc::new(std::sync::atomic::AtomicU64::new(0));
            let mut tasks = Vec::new();
            for input in inputs.into_iter().take(4) {
                let (mut activation, context) = renderer_activation_workbench(&workbench, &context).await;
                let produced = producers.clone();
                let sealed = sealed_count.clone();
                activation.activation_preview_observer = Some(Arc::new(move |event| {
                    match event {
                        ActivationPublicationObservation::RendererProducer => { produced.fetch_add(1, std::sync::atomic::Ordering::SeqCst); }
                        ActivationPublicationObservation::RendererSealed => { sealed.store(tidepool_codegen::prepared_program::CompiledProgram::successful_image_compilations(), std::sync::atomic::Ordering::SeqCst); }
                        _ => {}
                    }
                    Ok(())
                }));
                tasks.push(tokio::spawn(with_test_compiler_owner(async move {
                    activation.mount_activation_input(context, input, None, "()".into(), None, Vec::new()).await
                })));
            }
            let mut bindings = std::collections::BTreeSet::new();
            let mut generations = std::collections::BTreeSet::new();
            for (index, task) in tasks.into_iter().enumerate() {
                let prepared = task.await.unwrap().unwrap();
                assert_eq!(prepared.input_preview.trim(), (index + 1).to_string());
                assert!(bindings.insert(prepared.binding.raw()));
                assert!(generations.insert(prepared.admission.generation()));
            }
            assert_eq!(producers.load(std::sync::atomic::Ordering::SeqCst), 1);
            assert_eq!(tidepool_codegen::prepared_program::CompiledProgram::successful_image_compilations(), sealed_count.load(std::sync::atomic::Ordering::SeqCst), "four installations compile no images after the producer publishes complete native custody");
        }).await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn renderer_producer_and_waiter_release_machine_checkout() {
        with_test_compiler_owner(async {
            let (session, context, source, mut inputs, _root) = distinct_renderer_input_fixture();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(machines.clone(), source, None);
            let (mut first, first_context) =
                renderer_activation_workbench(&workbench, &context).await;
            let (mut second, second_context) =
                renderer_activation_workbench(&workbench, &context).await;
            let (mut abandoned, abandoned_context) =
                renderer_activation_workbench(&workbench, &context).await;
            let (producer_entered, producer_seen) = tokio::sync::oneshot::channel();
            let producer_entered = Arc::new(Mutex::new(Some(producer_entered)));
            let (resume_producer, hold_producer) = std::sync::mpsc::channel();
            let hold_producer = Mutex::new(hold_producer);
            first.activation_preview_observer = Some(Arc::new(move |event| {
                if matches!(event, ActivationPublicationObservation::RendererProducer) {
                    producer_entered.lock().take().unwrap().send(()).unwrap();
                    hold_producer
                        .lock()
                        .recv_timeout(Duration::from_secs(30))
                        .unwrap();
                }
                Ok(())
            }));
            let (waiter_entered, waiter_seen) = tokio::sync::oneshot::channel();
            let waiter_entered = Mutex::new(Some(waiter_entered));
            second.activation_preview_observer = Some(Arc::new(move |event| {
                if matches!(event, ActivationPublicationObservation::RendererWaiting) {
                    if let Some(signal) = waiter_entered.lock().take() {
                        let _ = signal.send(());
                    }
                }
                Ok(())
            }));
            let (abandoned_entered, abandoned_seen) = tokio::sync::oneshot::channel();
            let abandoned_entered = Mutex::new(Some(abandoned_entered));
            abandoned.activation_preview_observer = Some(Arc::new(move |event| {
                if matches!(event, ActivationPublicationObservation::RendererWaiting) {
                    if let Some(signal) = abandoned_entered.lock().take() {
                        let _ = signal.send(());
                    }
                }
                Ok(())
            }));
            let first_input = inputs.remove(0);
            let second_input = inputs.remove(0);
            let abandoned_input = inputs.remove(0);
            drop(inputs);
            let first_task =
                tokio::spawn(CompilerCloseOwner::current().unwrap().scope(async move {
                    first
                        .mount_activation_input(
                            first_context,
                            first_input,
                            None,
                            "()".into(),
                            None,
                            Vec::new(),
                        )
                        .await
                }));
            tokio::time::timeout(Duration::from_secs(30), producer_seen)
                .await
                .unwrap()
                .unwrap();
            let second_task =
                tokio::spawn(CompilerCloseOwner::current().unwrap().scope(async move {
                    second
                        .mount_activation_input(
                            second_context,
                            second_input,
                            None,
                            "()".into(),
                            None,
                            Vec::new(),
                        )
                        .await
                }));
            tokio::time::timeout(Duration::from_secs(30), waiter_seen)
                .await
                .unwrap()
                .unwrap();
            // Real checkout admission succeeds while one native producer is
            // held and another activation awaits its shared result.
            let (session, receipt) = machines
                .checkout_run(context.placement.session)
                .unwrap()
                .into_parts();
            let holes = session
                .parked_holes()
                .into_iter()
                .map(str::to_owned)
                .collect();
            machines.settle_suspended(receipt, session, holes);
            let abandoned_task =
                tokio::spawn(CompilerCloseOwner::current().unwrap().scope(async move {
                    abandoned
                        .mount_activation_input(
                            abandoned_context,
                            abandoned_input,
                            None,
                            "()".into(),
                            None,
                            Vec::new(),
                        )
                        .await
                }));
            tokio::time::timeout(Duration::from_secs(30), abandoned_seen)
                .await
                .unwrap()
                .unwrap();
            abandoned_task.abort();
            assert!(matches!(abandoned_task.await, Err(error) if error.is_cancelled()));
            // Dropping a shared-result waiter cannot cancel the held producer.
            resume_producer.send(()).unwrap();
            let first = first_task.await.unwrap().unwrap();
            let second = second_task.await.unwrap().unwrap();
            assert_eq!(first.input_preview.trim(), "1");
            assert_eq!(second.input_preview.trim(), "2");
            assert_ne!(first.binding, second.binding);
            assert_ne!(first.admission.generation(), second.admission.generation());
        })
        .await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn cancelled_renderer_producer_retains_sealed_code_for_fresh_child() {
        with_test_compiler_owner(async {
            let (session, context, source, mut inputs, _root) = distinct_renderer_input_fixture();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(machines, source, None);
            let (mut first, first_context) =
                renderer_activation_workbench(&workbench, &context).await;
            let (second, second_context) =
                renderer_activation_workbench(&workbench, &context).await;
            let (sealed, sealed_seen) = tokio::sync::oneshot::channel();
            let sealed = Mutex::new(Some(sealed));
            let (resume, held) = std::sync::mpsc::channel();
            let held = Mutex::new(held);
            let (released, released_seen) = tokio::sync::oneshot::channel();
            let released = Mutex::new(Some(released));
            first.activation_preview_observer = Some(Arc::new(move |event| {
                if matches!(event, ActivationPublicationObservation::RendererSealed) {
                    sealed.lock().take().unwrap().send(()).unwrap();
                    held.lock().recv_timeout(Duration::from_secs(60)).unwrap();
                    let _ = released.lock().take().unwrap().send(());
                }
                Ok(())
            }));
            let first_input = inputs.remove(0);
            let second_input = inputs.remove(0);
            drop(inputs);
            let submissions = tidepool_extract_cmd::extract_spawn_count();
            let first_task =
                tokio::spawn(CompilerCloseOwner::current().unwrap().scope(async move {
                    first
                        .mount_activation_input(
                            first_context,
                            first_input,
                            None,
                            "()".into(),
                            None,
                            Vec::new(),
                        )
                        .await
                }));
            tokio::time::timeout(Duration::from_secs(60), sealed_seen)
                .await
                .unwrap()
                .unwrap();
            assert_eq!(tidepool_extract_cmd::extract_spawn_count(), submissions + 2);
            first_task.abort();
            assert!(matches!(first_task.await, Err(error) if error.is_cancelled()));
            let fresh = second
                .mount_activation_input(
                    second_context,
                    second_input,
                    None,
                    "()".into(),
                    None,
                    Vec::new(),
                )
                .await
                .unwrap();
            assert_eq!(fresh.input_preview.trim(), "2");
            assert_eq!(
                tidepool_extract_cmd::extract_spawn_count(),
                submissions + 3,
                "fresh child issues its interface and reuses the cancelled producer's sealed code"
            );
            resume.send(()).unwrap();
            tokio::time::timeout(Duration::from_secs(60), released_seen)
                .await
                .unwrap()
                .unwrap();
        })
        .await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn cancelled_renderer_producer_retries_only_after_native_close() {
        with_test_compiler_owner(async {
            let (session, context, source, mut inputs, _root) = distinct_renderer_input_fixture();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(machines, source, None);
            let (mut first, first_context) =
                renderer_activation_workbench(&workbench, &context).await;
            let (mut second, second_context) =
                renderer_activation_workbench(&workbench, &context).await;
            let (started, started_seen) = tokio::sync::oneshot::channel();
            let started = Mutex::new(Some(started));
            let (waiting, waiting_seen) = tokio::sync::oneshot::channel();
            let waiting = Mutex::new(Some(waiting));
            let (resume, held) = std::sync::mpsc::channel();
            let held = Mutex::new(held);
            let producers = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let counted = producers.clone();
            let observer: ActivationPublicationObserver = Arc::new(move |event| {
                match event {
                    ActivationPublicationObservation::RendererProducer => {
                        if counted.fetch_add(1, std::sync::atomic::Ordering::SeqCst) == 0 {
                            started.lock().take().unwrap().send(()).unwrap();
                            held.lock().recv_timeout(Duration::from_secs(60)).unwrap();
                        }
                    }
                    ActivationPublicationObservation::RendererWaiting => {
                        if let Some(waiting) = waiting.lock().take() {
                            let _ = waiting.send(());
                        }
                    }
                    _ => {}
                }
                Ok(())
            });
            first.activation_preview_observer = Some(observer.clone());
            second.activation_preview_observer = Some(observer);
            let first_input = inputs.remove(0);
            let second_input = inputs.remove(0);
            drop(inputs);
            let first_task =
                tokio::spawn(CompilerCloseOwner::current().unwrap().scope(async move {
                    first
                        .mount_activation_input(
                            first_context,
                            first_input,
                            None,
                            "()".into(),
                            None,
                            Vec::new(),
                        )
                        .await
                }));
            tokio::time::timeout(Duration::from_secs(60), started_seen)
                .await
                .unwrap()
                .unwrap();
            first_task.abort();
            assert!(matches!(first_task.await, Err(error) if error.is_cancelled()));
            let second_task =
                tokio::spawn(CompilerCloseOwner::current().unwrap().scope(async move {
                    second
                        .mount_activation_input(
                            second_context,
                            second_input,
                            None,
                            "()".into(),
                            None,
                            Vec::new(),
                        )
                        .await
                }));
            tokio::time::timeout(Duration::from_secs(60), waiting_seen)
                .await
                .unwrap()
                .unwrap();
            assert_eq!(
                producers.load(std::sync::atomic::Ordering::SeqCst),
                1,
                "cancelled producer retains the slot until its native ticket settles"
            );
            resume.send(()).unwrap();
            let fresh = second_task.await.unwrap().unwrap();
            assert_eq!(fresh.input_preview.trim(), "2");
            assert_eq!(
                producers.load(std::sync::atomic::Ordering::SeqCst),
                2,
                "confirmed failed native close permits exactly one fresh producer"
            );
        })
        .await;
    }

    #[tokio::test]
    async fn cached_renderer_recheckout_refuses_stale_mount_and_preserves_ready_code() {
        with_test_compiler_owner(async {
            let (session, context, source, mut inputs, _root) = distinct_renderer_input_fixture();
            let machines = Arc::new(ActorMachineRegistry::new());
            machines.insert_idle(context.placement.session, Box::new(session));
            let workbench = ResidentActorWorkbench::new(machines.clone(), source, None);
            let (first, first_context) = renderer_activation_workbench(&workbench, &context).await;
            let (mut stale, stale_context) = renderer_activation_workbench(&workbench, &context).await;
            let (third, third_context) = renderer_activation_workbench(&workbench, &context).await;
            let first_input = inputs.remove(0);
            let stale_input = inputs.remove(0);
            let third_input = inputs.remove(0);
            drop(inputs);
            let submissions = tidepool_extract_cmd::extract_spawn_count();
            let warm = first.mount_activation_input(first_context, first_input, None, "()".into(), None, Vec::new()).await.unwrap();
            assert_eq!(warm.input_preview.trim(), "1");
            assert_eq!(tidepool_extract_cmd::extract_spawn_count(), submissions + 2);
            let observed = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let invalidated = observed.clone();
            let session_id = context.placement.session;
            stale.activation_preview_observer = Some(Arc::new(move |event| {
                if let ActivationPublicationObservation::RendererSelected(admission) = event {
                    let (mut session, receipt) = machines.checkout_run(session_id).unwrap().into_parts();
                    session.retire_scope(admission.view().lexical_scope());
                    let holes = session.parked_holes().into_iter().map(str::to_owned).collect();
                    machines.settle_suspended(receipt, session, holes);
                    invalidated.store(true, std::sync::atomic::Ordering::SeqCst);
                }
                Ok(())
            }));
            let refused = stale.mount_activation_input(stale_context, stale_input, None, "()".into(), None, Vec::new()).await;
            assert!(observed.load(std::sync::atomic::Ordering::SeqCst));
            assert!(matches!(refused, Err(ResidentActorWorkbenchError::ActivationBindingCommitted { source, .. })
                if matches!(*source, ResidentActorWorkbenchError::Resident(_))));
            assert_eq!(tidepool_extract_cmd::extract_spawn_count(), submissions + 3);
            let fresh = third.mount_activation_input(third_context, third_input, None, "()".into(), None, Vec::new()).await.unwrap();
            assert_eq!(fresh.input_preview.trim(), "3");
            assert_ne!(fresh.binding, warm.binding);
            assert_eq!(tidepool_extract_cmd::extract_spawn_count(), submissions + 4,
                "stale affine authority cannot invalidate retained renderer code");
        }).await;
    }

